'Restrict_Master_Data_By_Warehouse' => 'Restreindre les données de base par entrepôt',
'Restrict_Master_Data_By_Warehouse_Help' => 'Lorsque cette option est activée, un utilisateur affecté à des entrepôts précis ne voit que les produits, clients, fournisseurs, marques et catégories liés à ces entrepôts. Les fiches encore inutilisées restent visibles, afin qu\'une fiche nouvellement créée ne soit jamais masquée. Les ventes, achats et retours sont toujours restreints et ne dépendent pas de cette option.',
'Restrict_Products_By_Warehouse' => 'Restreindre les produits par entrepôt',
'Restrict_Products_By_Warehouse_Help' => 'Chaque produit a un entrepôt d\'origine — l\'agence pour laquelle il a été créé. Lorsque cette option est activée, un utilisateur affecté à des entrepôts précis ne voit, ne vend et ne modifie que les produits dont l\'entrepôt d\'origine est le sien, ainsi que ceux qui ont un stock réel dans l\'un de ses entrepôts (reçu par transfert ou par achat). Les utilisateurs ayant accès à tous les entrepôts voient toujours tout. La boutique en ligne suit la même règle : elle ne liste que les produits des entrepôts sélectionnés dans les Paramètres de la boutique.',
'Virtual_Combo_Stock' => 'Stock virtuel des combos',
'Virtual_Combo_Stock_Help' => 'Lorsque cette option est activée, un produit combo n\'a pas de stock propre : sa disponibilité correspond au nombre de combos que ses produits composants peuvent encore former, et la vente d\'un combo déduit le stock des composants. Lorsqu\'elle est désactivée, les combos doivent d\'abord être assemblés en stock au moyen d\'un ajustement.',
'Virtual_Combo_Stock_Warning' => 'À choisir de préférence avant de vendre des combos. Une fois des combos vendus ou retournés, changer ce mode fait que les modifications, suppressions et retours ultérieurs de ces documents corrigent le stock dans le mauvais sens.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Activer le stock virtuel des combos ?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Les combos seront vendus directement à partir de leurs produits composants, et leur propre stock ne sera plus utilisé.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Désactiver le stock virtuel des combos ?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Les combos reviendront à leur propre stock, qui doit être assemblé à partir des composants au moyen d\'un ajustement avant de pouvoir être vendu.',
'Home_Warehouse' => 'Entrepôt d\'origine',
'Home_Warehouse_Hint' => 'L\'agence à laquelle ce produit appartient. Les utilisateurs limités à d\'autres entrepôts ne le verront pas tant qu\'aucun stock ne leur est transféré.',
'Home_Warehouse_Required' => 'Choisissez l\'entrepôt auquel ce produit appartient.',
'Combo_products_required' => 'Ajoutez au moins un produit au combo.',
'Customer_Performance_Help' => 'Afficher un score de performance et une note sur la fiche client, calculés à partir de la fiabilité de paiement, de la récence des achats et du taux de retour.',
'Product_Supplier' => 'Fournisseur sur les produits',
'Product_Supplier_Help' => 'Ajoute un champ fournisseur par défaut au formulaire produit, l\'affiche en colonne dans la liste des produits et permet de filtrer les produits par fournisseur pour établir une liste de réapprovisionnement.',
'Default_Supplier_Hint' => 'Le fournisseur auprès duquel vous réapprovisionnez habituellement ce produit. Filtrez la liste des produits par fournisseur pour voir tout ce qu\'il faut lui commander.',
'Account_Ledger' => 'Grand livre du compte',
'Closing_Balance' => 'Solde de clôture',
'Recon_Intro' => 'Compare le solde opérationnel de chaque compte de caisse et de banque au solde du grand livre de son compte comptable lié. Cette page est en lecture seule : elle ne modifie jamais aucun des deux soldes.',
'Recon_Auto_Off' => 'Les écritures automatiques sont désactivées : les nouvelles transactions ne sont pas passées au grand livre et apparaîtront comme écritures manquantes. Activez-les dans Paramètres → Activation des fonctionnalités.',
'Recon_Operational_Balance' => 'Solde opérationnel',
