'Recon_Unreconciled' => 'Comptes non rapprochés',
'Recon_Reconciled' => 'Rapproché',
'Recon_Out_Of_Balance' => 'Déséquilibré',
'Recon_Not_Linked' => 'Ce compte n\'a encore aucune écriture au grand livre.',
'Recon_Unassigned_Cash' => 'Les paiements enregistrés sans compte ont été passés au compte général Caisse (Cash) du grand livre ({amount}). Ils ne figurent dans aucun des comptes ci-dessous.',
'Recon_Details' => 'Détails',
