'Tg_Bot_Token_Help' => 'Créez un bot avec {botfather} dans Telegram et collez son jeton ici. Il est stocké en écriture seule et n\'est plus jamais affiché en entier.',
'Tg_Chat_ID' => 'ID du chat',
'Tg_Chat_ID_Placeholder' => 'ex. -1001234567890 pour un groupe, ou un ID utilisateur',
'Tg_Chat_ID_Help' => 'Ajoutez le bot à votre groupe ou canal, puis récupérez l\'ID du chat — par exemple en transférant un message à {userinfobot}, ou à partir de la réponse de l\'API {getUpdates} du bot.',
'Tg_Pick_Events' => 'Choisissez les événements à envoyer',
'Tg_Test_Sent' => 'Message de test envoyé — vérifiez votre chat Telegram.',
'Tg_Cron_Line_Copied' => 'Ligne cron copiée',
'Tg_Guide_Lead' => 'Comment recevoir les notifications de Stocky dans un chat, un groupe ou un canal Telegram.',
'Tg_Guide_Lead_Cron' => 'La ligne cron ci-dessous est générée pour ce serveur ; elle peut donc y être copiée telle quelle.',
'Tg_Guide_Set_It_Up' => 'Configuration',
'Tg_Guide_Step1_Title' => 'Créer le bot',
'Tg_Guide_Step1_Body' => 'Dans Telegram, ouvrez une conversation avec {botfather}, envoyez {newbot}, puis choisissez un nom et un nom d\'utilisateur pour le bot. BotFather répond avec un {botToken} tel que {example} — copiez-le.',
'Tg_Guide_Bot_Token_Lower' => 'jeton de bot',
'Tg_Guide_Step2_Title' => 'Trouver l\'ID du chat',
'Tg_Guide_Step2_Intro' => 'L\'ID nécessaire dépend de la destination des messages :',
'Tg_Guide_Own_Chat' => 'Votre propre chat',
'Tg_Guide_Own_Chat_Item' => '{label} — envoyez d\'abord un message quelconque à votre nouveau bot (un bot ne peut pas démarrer une conversation), puis écrivez à {userinfobot} : il vous répond avec votre ID utilisateur.',
'Tg_Guide_Group' => 'Un groupe',
'Tg_Guide_Group_Item' => '{label} — ajoutez le bot au groupe et publiez-y un message.',
'Tg_Guide_Channel' => 'Un canal',
'Tg_Guide_Channel_Item' => '{label} — ajoutez le bot comme {admin} du canal et publiez-y un message.',
'Tg_Guide_Administrator' => 'administrateur',
'Tg_Guide_GetUpdates_Intro' => 'Pour un groupe ou un canal, ouvrez cette adresse dans un navigateur avec votre propre jeton, puis actualisez-la après avoir publié :',
'Tg_Guide_GetUpdates_Note' => 'Recherchez {chatId}. L\'ID d\'un groupe ou d\'un canal est négatif, ex. {example} — copiez-le en entier, signe moins compris.',
'Tg_Guide_Step3_Title' => 'Le connecter ici',
'Tg_Guide_Step3_Body' => 'Dans l\'onglet {settings}, collez le jeton du bot et l\'ID du chat, choisissez {allEvents} ou seulement ceux qui vous intéressent ({events}…), activez {enable} et enregistrez. Cliquez ensuite sur {sendTest}.',
'Tg_Guide_State_Enabled' => 'activé',
'Tg_Guide_State_Saved_Off' => 'enregistré, mais désactivé',
'Tg_Guide_State_Not_Configured' => 'pas encore configuré',
'Tg_Guide_Chat_Id' => 'chat {id}',
'Tg_Guide_How_Sent' => 'Comment les messages sont envoyés',
'Tg_Guide_A_Title' => 'Immédiatement — rien à installer',
'Tg_Guide_A_Body' => 'Une vente, un achat, un paiement ou une dépense enregistré dans Stocky — au POS ou dans l\'administration — est envoyé à Telegram {rightAfter} son enregistrement, dans la même requête. Pas d\'entrée cron, pas de worker de file d\'attente, et le caissier n\'attend jamais Telegram : la vente a déjà reçu sa réponse lorsque le message part.',
'Tg_Guide_Right_After' => 'juste après',
'Tg_Guide_B_Title' => 'L\'entrée cron — pour les nouvelles tentatives et les événements en arrière-plan',
'Tg_Guide_B_Body' => 'Deux types de messages attendent plutôt dans la file d\'attente propre à Telegram : un envoi qui a échoué (Telegram momentanément injoignable), retenté jusqu\'à trois fois de plus au cours des minutes suivantes ; et les événements déclenchés en dehors de l\'administration — commandes importées depuis WooCommerce ou Shopify, commandes artisan. Cette entrée cron les envoie, et rien d\'autre :',
'Tg_Guide_B_Note' => 'Toutes les minutes, c\'est la bonne fréquence : une exécution sans rien en attente se termine immédiatement. Sous cPanel, cela se place dans {cronJobs} — utilisez le chemin complet vers PHP 8.2+ si {php} est plus ancien. Sous Windows, utilisez le Planificateur de tâches avec le programme {php2}, les arguments {args}, démarré dans {path}.',
'Tg_Guide_N_Waiting' => '{n} en attente d\'envoi',
'Tg_Guide_Nothing_Waiting' => 'rien en attente',
'Tg_Guide_N_Gave_Up' => '{n} abandonné(s) après les nouvelles tentatives',
'Tg_Guide_Growing_Hint' => '— si ce nombre ne cesse d\'augmenter, l\'entrée cron ne s\'exécute pas.',
'Tg_Guide_Without_Cron' => 'Sans l\'entrée cron, tout ce qui est enregistré dans Stocky arrive quand même instantanément ; vous perdez seulement les nouvelles tentatives et les commandes importées.',
'Tg_Guide_Else_Title' => 'Tout le reste',
'Tg_Guide_Else_Body' => 'Les messages des événements déclenchés en arrière-plan sont acheminés par la plateforme — il n\'y a rien à configurer.',
'Tg_Guide_Not_Arrive' => 'Si rien n\'arrive',
'Tg_Guide_Err_401' => '{code} — le jeton du bot est incorrect. Collez-le à nouveau depuis BotFather.',
'Tg_Guide_Err_400' => '{code} — ID de chat incorrect, ou le bot n\'est pas dans le groupe. Pour un chat personnel, écrivez d\'abord au bot.',
'Tg_Guide_Err_403' => '{code} — rajoutez le bot au groupe, ou comme administrateur du canal.',
'Tg_Guide_Test_Works' => 'Le test fonctionne mais pas les ventes',
'Tg_Guide_Test_Works_Item' => '{label} — vérifiez que l\'événement est coché (ou que {allEvents} est choisi) et que l\'interrupteur est activé.',
'Tg_Guide_Imported_Never' => 'Les commandes importées n\'arrivent jamais',
'Tg_Guide_Imported_Never_Item' => '{label} — l\'entrée cron ci-dessus ne s\'exécute pas.',
'Jumia_Hero_Title' => 'Synchronisation de la marketplace Jumia',
'Jumia_Hero_Desc' => 'Envoyez les prix et le stock vers vos annonces Jumia Seller Center et importez les commandes de la marketplace comme ventes.',
'Jumia_Api_Url_Label' => 'URL de l\'API (endpoint Seller Center de votre pays)',
'Jumia_Account_Email' => 'E-mail du compte (User ID)',
'Jumia_Prices_Stock' => 'Prix et stock',
'Jumia_Push_Card_Title' => 'Envoyer les prix et le stock vers Jumia',
'Jumia_Push_Desc' => 'Envoie le prix et la quantité actuels de chaque produit (et variante) dont le SKU correspond au {sellerSku} de l\'annonce Jumia. Les mises à jour sont soumises sous forme de flux Seller Center et appliquées de manière asynchrone — l\'ID du flux est consigné dans l\'onglet Journaux, et les rejets par article apparaissent dans l\'écran d\'état des flux de Seller Center.',
'Jumia_Push_Prices_Stock' => 'Envoyer les prix et le stock',
'Jumia_Orders_Desc' => 'Importe les commandes de la marketplace comme ventes (références du type {ref}), associées à vos produits par Seller SKU. Les commandes déjà importées et annulées sont ignorées, vous pouvez donc récupérer régulièrement sans risque. Les paiements ne sont marqués comme payés que pour les commandes livrées (Jumia fonctionne majoritairement en paiement à la livraison).',
'Jumia_Guide_1' => 'Dans Jumia {sellerCenter}, ouvrez Settings → {integrationMgmt} et générez une clé API.',
'Jumia_Guide_2' => 'Saisissez l\'URL de l\'API de votre pays (ex. {ng} pour le Nigeria, {ke} pour le Kenya, {eg} pour l\'Égypte), l\'e-mail de votre compte Seller Center et la clé — puis lancez {test}.',
'Jumia_Guide_3' => 'Assurez-vous que le {sellerSku} de chaque annonce Jumia est égal au code produit Stocky — c\'est l\'identifiant utilisé à la fois pour l\'envoi du stock et l\'association des commandes.',
'Jumia_Guide_4' => 'Envoyez les prix et le stock après chaque modification de l\'inventaire ; récupérez les commandes régulièrement (cette API Jumia ne propose pas de webhooks).',
'Jumia_Guide_5' => 'La création de nouvelles annonces reste dans Seller Center — Jumia exige des attributs propres à chaque catégorie et une validation des images que seul son portail gère correctement.',
'Mc_Hero_Title' => 'Synchronisation d\'audience Mailchimp',
'Mc_Hero_Desc' => 'Alimentez une audience Mailchimp avec vos clients afin de mener des campagnes e-mail sur votre véritable base clients.',
'Mc_Account_Audience' => 'Compte et audience',
'Mc_Api_Key_Placeholder' => 'ex. a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Audience',
'Mc_N_Members' => '({n} membres)',
'Mc_Load_Audiences_To_Pick' => 'Chargez les audiences pour en choisir une',
'Mc_Load_Audiences' => 'Charger les audiences',
'Mc_Double_Opt_In_Label' => 'Double opt-in — les nouveaux membres reçoivent un e-mail de confirmation avant leur inscription',
'Mc_Recommended_GDPR' => '(recommandé pour le RGPD)',
'Mc_Auto_Sync_New' => 'Synchroniser automatiquement les nouveaux clients dès leur création',
'Mc_With_Email' => 'Avec une adresse e-mail',
'Mc_Push_Desc' => 'Ajoute ou met à jour chaque client disposant d\'une adresse e-mail dans l\'audience sélectionnée (nom et téléphone inclus). Les membres existants conservent leur statut d\'abonnement — personne s\'étant désabonné n\'est réabonné. Les clients sans e-mail sont ignorés.',
'Mc_Double_Opt_In_Off' => 'Le double opt-in est désactivé',
'Mc_Double_Opt_In_Off_Desc' => 'Les nouveaux membres seront ajoutés comme abonnés sans e-mail de confirmation. Ne le faites que pour les clients ayant déjà accepté de recevoir des communications marketing.',
'Mc_Guide_1' => 'Dans Mailchimp, ouvrez {path} et créez une clé (elle se termine par {suffix} — ce suffixe correspond à votre datacenter).',
'Mc_Guide_2' => 'Collez la clé ici, enregistrez, puis cliquez sur {load} et choisissez l\'audience à alimenter.',
'Mc_Guide_3' => 'Laissez le {doi} activé, sauf si vos clients ont déjà consenti à recevoir des e-mails marketing.',
'Mc_Double_Opt_In_Lower' => 'double opt-in',
'Mc_Guide_4' => 'Lancez {push} pour l\'alimentation initiale ; activez la {autoSync} pour que les nouveaux clients soient ajoutés automatiquement.',
'Mc_Auto_Sync_Lower' => 'synchronisation automatique',
'Mc_Consent_Matters' => 'Le consentement compte',
'Mc_Consent_Desc' => 'Envoyer des e-mails à des personnes n\'ayant jamais accepté le marketing peut enfreindre le RGPD/CAN-SPAM et entraîner la suspension de votre compte Mailchimp. Le double opt-in confie la confirmation à Mailchimp — le choix sûr par défaut.',
'Mc_No_Audiences' => 'Aucune audience trouvée sur ce compte.',
'Presta_Hero_Desc' => 'Synchronisez les produits, le stock et les commandes avec votre boutique PrestaShop via son API webservice.',
'Presta_Webservice_Key' => 'Clé webservice',
'Presta_Key_Placeholder' => 'Depuis Paramètres avancés → Webservice',
'Presta_Key_Help' => 'Activez le webservice dans PrestaShop (Paramètres avancés → Webservice), créez une clé avec des permissions sur products, stock_availables, orders et customers, puis collez-la ici. Stockée en écriture seule.',
'Presta_Shop_Language_ID' => 'ID de langue de la boutique',
'Presta_Language_Help' => 'ID de langue utilisé pour les noms de produits lors de l\'envoi (1 = la première langue de la boutique).',
'Presta_Push_Desc' => 'Crée les produits simples manquants sur PrestaShop (avec leur stock actuel). Les produits déjà liés et les produits à variantes sont ignorés — continuez à modifier les détails des produits dans PrestaShop, ou récupérez-les pour actualiser la copie locale.',
'Presta_Pull_Desc' => 'Importe les produits PrestaShop en associant les produits existants par référence (SKU) et en créant les autres. Les déclinaisons sont importées comme leur produit parent.',
'Presta_Reset_Confirm' => 'Réinitialiser les liens produits ? L\'historique des commandes conserve ses liens.',
'Presta_Stock_Desc' => 'Met à jour le stock de la boutique (stock_availables) pour chaque produit lié.',
'Presta_Orders_Desc' => 'Importe les commandes de la boutique comme ventes (références du type {ref}), les plus récentes en premier. Les commandes déjà importées et annulées sont ignorées, vous pouvez donc récupérer régulièrement sans risque. PrestaShop ne propose pas de webhooks — lancez cette opération après les périodes chargées.',
'Presta_Guide_1' => 'Dans le back-office PrestaShop, ouvrez {path} et activez le webservice.',
'Presta_Guide_2' => 'Ajoutez une nouvelle clé en accordant {vae} sur {products} et {stock}, et {view} sur {orders} et {customers}.',
'Presta_Guide_3' => 'Collez l\'URL de la boutique et la clé dans l\'onglet Connexion, enregistrez et lancez {test}.',
'Presta_Guide_4' => 'Récupérez d\'abord les produits si la boutique possède déjà un catalogue (association par référence/SKU) ; envoyez pour créer les produits simples manquants.',
'Presta_Guide_5' => 'Envoyez le stock à chaque changement de quantité et récupérez les commandes régulièrement — PrestaShop ne propose pas de webhooks, les commandes n\'arrivent donc que lorsque vous les récupérez.',
'Presta_Identity_Title' => 'L\'identifiant produit est la référence (SKU)',
'Presta_Identity_Desc' => 'Le code produit Stocky est associé à la référence PrestaShop. Gardez des références cohérentes des deux côtés ; les déclinaisons (variantes) sont associées par référence dans les commandes, mais ne sont pas envoyées dans cette version.',
'Gs_Hero_Title' => 'Exports Google Sheets',
