'Gs_Redirect_Uri_Title' => 'URI de redirection pour le client OAuth Google',
'Gs_Export_Desc' => 'Chaque export réécrit entièrement son onglet (en-tête + toutes les lignes) : la feuille est donc toujours un instantané complet et à jour. Les grands volumes de données sont envoyés par lots — laissez la page ouverte jusqu\'à ce que le compteur s\'arrête.',
