'Gs_Job_Customers_Desc' => 'Tous les clients avec leurs coordonnées.',
'Gs_Guide_1' => 'Créez un projet sur {console} et activez l\'{api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Configurez l\'{consent} (External). Tant qu\'il reste en « Testing », ajoutez votre compte Google comme utilisateur test — notez que les jetons d\'actualisation en mode test expirent au bout de 7 jours ; {publish} donc l\'application pour une connexion permanente.',
