'Xero_Push_Customers_Desc' => 'Crée ou met à jour un contact Xero pour chaque client. Un client dont le nom existe déjà dans Xero est lié à ce contact.',
'Xero_Push_Sales_As_Invoices' => 'Envoyer les ventes comme factures',
'Xero_Push_Invoices_Desc' => 'Crée une facture AUTHORISED par vente (numéro de facture = Ref de la vente), avec les lignes de la vente ainsi que des lignes de livraison, de remise et de taxe pour que le total Xero corresponde au total de la vente. Les ventes déjà présentes dans Xero sont ignorées — les factures ne sont jamais modifiées. Les contacts manquants sont créés à la volée.',
'Xero_Push_Invoices' => 'Envoyer les factures',
'Xero_Reset_Contact_Confirm' => 'Réinitialiser les liens des contacts ? Le prochain envoi les reliera ou les recréera.',
'Xero_Reset_Contact_Links' => 'Réinitialiser les liens des contacts',
'Xero_Guide_1' => 'Créez une {webApp} sur {link} (My Apps → New app).',
'Xero_Web_App' => 'Web app',
'Xero_Guide_2' => 'Enregistrez l\'URI de redirection affichée dans l\'onglet Connexion.',
