'Xero_Guide_4' => 'Cliquez sur {connect}, connectez-vous et choisissez l\'organisation à connecter.',
'Xero_Guide_5' => 'Vérifiez les codes de compte : le compte de ventes reçoit les lignes de facture ; renseignez un code de compte bancaire si les ventes payées doivent aussi enregistrer des paiements.',
'Xero_Guide_6' => 'Envoyez d\'abord les clients, puis les factures. Les numéros de facture sont les Refs des ventes : Xero rejette donc les doublons même si les liens sont réinitialisés.',
'Xero_Tax_Inclusive_Title' => 'Les montants sont envoyés tels quels, taxes incluses',
'Xero_Tax_Inclusive_Desc' => 'Les factures utilisent des lignes NoTax qui reproduisent exactement la vente (articles + livraison − remise + taxe), de sorte que les totaux Xero sont toujours égaux aux totaux Stocky. Votre comptable peut réaffecter les lignes de taxe et de livraison aux comptes appropriés dans Xero.',
