'Salla_Variants_Linked' => 'Variantes liées',
'Salla_Push_Desc' => 'Crée ou met à jour les produits simples sur Salla par SKU. Les produits à variantes sont ignorés dans cette version — récupérez-les plutôt depuis Salla, ou associez-les par SKU.',
'Salla_Only_Unlinked' => 'Uniquement les produits pas encore liés',
'Salla_Pull_Desc' => 'Importe les produits Salla (variantes comprises), en associant les produits existants par SKU et en créant les autres.',
'Salla_Reset_Confirm' => 'Réinitialiser les liens des produits et des variantes ? L\'historique des commandes conserve ses liens.',
'Salla_Stock_Desc' => 'Envoie les quantités actuelles de chaque produit lié (par SKU) et de chaque variante liée.',
'Salla_Orders_Desc' => 'Les nouvelles commandes Salla arrivent normalement d\'elles-mêmes via les webhooks et deviennent des ventes. Utilisez cette récupération pour rattraper les commandes passées avant la configuration du webhook — les commandes déjà importées sont ignorées.',
'Salla_Guide_1' => 'Créez une application (privée) sur {link} et choisissez le flux d\'autorisation {mode}.',
