'Fbr_Guide_What_Body' => 'En vertu du SRO 69(I)/2025, le Federal Board of Revenue (Pakistan) exige des entreprises intégrées qu\'elles déclarent leurs factures de vente par voie électronique, en temps réel, via l\'API PRAL Digital Invoicing (DI). Chaque vente acceptée reçoit un numéro de facture FBR officiel, et les reçus doivent afficher ce numéro accompagné d\'un QR code de vérification.',
'Fbr_Guide_Steps_Title' => 'Étapes de mise en production',
'Fbr_Guide_Step_1' => 'Inscrivez-vous sur le portail de facturation électronique FBR IRIS et obtenez un jeton de sécurité {sandbox}.',
'Fbr_Guide_Step_2' => 'Configurez votre profil vendeur dans l\'onglet Configuration (NTN/CNIC, nom de l\'entreprise, province, adresse), collez le jeton et activez l\'intégration avec l\'environnement défini sur {sandbox}.',
'Fbr_Guide_Step_3' => 'Effectuez des ventes de test couvrant le(s) scénario(s) que la FBR vous a attribué(s) (choisissez le scénario dans le champ Scénario bac à sable). Vérifiez dans l\'onglet Documents qu\'elles reviennent avec le statut {valid}.',
'Fbr_Guide_Step_4' => 'Une fois vos tests en bac à sable approuvés par la FBR, obtenez le jeton {production} sur le portail, collez-le ici et basculez l\'environnement sur {production}.',
'Fbr_Guide_Step_5' => 'Les reçus affichent automatiquement le numéro de facture FBR et le QR code dès qu\'une vente est acceptée — aucune étape supplémentaire n\'est nécessaire au point de vente.',
'Fbr_Sandbox_Lower' => 'bac à sable',
'Fbr_Production_Lower' => 'production',
'Fbr_Guide_Note_1' => 'Définissez les codes SH par produit dans le formulaire produit (champ « Code SH »). Le code SH par défaut configuré ici n\'est utilisé que pour les produits qui n\'en ont pas.',
'Fbr_Guide_Note_2' => 'Les clients de passage non enregistrés sont déclarés à la FBR comme « Unregistered ».',
'Fbr_Guide_Note_3' => 'Les acheteurs enregistrés doivent avoir leur NTN saisi dans le champ Numéro fiscal du client pour être déclarés comme enregistrés.',
'Fbr_Guide_Note_4' => 'Les soumissions échouées ou invalides peuvent être relancées depuis l\'onglet Documents après correction de la cause ; l\'onglet Journaux affiche les échanges bruts avec l\'API pour le dépannage.',
