'Woo_WordPress_App_Password' => 'Mot de passe d\'application WordPress',
'Woo_Automatic_Sync' => 'Synchronisation automatique',
'Woo_Auto_Sync_Intro' => 'Envoyez vers WooCommerce les modifications effectuées dans Stocky au fur et à mesure, sans ouvrir cette page. Chaque envoi s\'exécute juste après l\'enregistrement de l\'action, de sorte que le caissier n\'attend jamais WooCommerce. Les résultats apparaissent dans l\'onglet Journaux.',
'Woo_Auto_Sync_Products_Help' => 'Un produit créé, modifié ou dupliqué dans Stocky est envoyé à WooCommerce (détails, prix, variantes, images, stock). Les imports en masse ne sont pas envoyés ; après un import, utilisez Synchroniser — POS → WooCommerce dans l\'onglet Produits.',
'Woo_Auto_Sync_Stock_Help' => 'Tout mouvement de stock (vente POS, vente, retour, achat, ajustement, transfert) met à jour la quantité des produits concernés sur WooCommerce. Seuls les produits déjà liés à WooCommerce sont mis à jour.',
'Woo_Sync_Tuning' => 'Réglage de la synchronisation',
'Woo_Sync_Tuning_Intro' => 'Les valeurs par défaut conviennent à la plupart des boutiques. Ne les modifiez que si la synchronisation est lente ou expire sur votre hébergement. Chaque valeur est limitée à une plage sûre, et vider un champ rétablit sa valeur par défaut.',
'Woo_Sync_Guide' => 'Guide de synchronisation WooCommerce',
'Woo_Guide_Getting_Keys' => 'Obtenir les clés API',
'Woo_Guide_Keys_1' => 'Dans WooCommerce : WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Cliquez sur Add key, choisissez Read/Write, puis copiez la Consumer key et le Consumer secret.',
'Woo_Guide_Keys_3' => 'URL de la boutique : l\'URL de votre site sans barre oblique finale (ex. {example}).',
'Woo_Guide_WP_Title' => 'Nom d\'utilisateur WP et mot de passe d\'application (facultatif)',
'Woo_Guide_WP_Intro' => 'Ces champs ne servent qu\'aux images des produits. L\'API WooCommerce (URL de la boutique + Consumer key/secret) gère la synchronisation des produits, du stock, des catégories, des marques, des clients et des commandes ; l\'API REST WordPress gère la Media Library (recherche et téléversement d\'images).',
'Woo_Guide_WP_1' => 'Lors de la synchronisation des produits ou du stock, Stocky peut joindre les images des produits : il recherche d\'abord une image existante par nom de fichier dans la Media Library de WordPress ; s\'il n\'en trouve pas, il téléverse l\'image via l\'API WordPress.',
'Woo_Guide_WP_2' => 'Utilisez un utilisateur WordPress pouvant gérer les médias (ex. Administrator). Créez un mot de passe d\'application dans WordPress : Users → Profile (ou votre utilisateur) → Application Passwords — ajoutez-en un nouveau et collez-le ici.',
'Woo_Guide_WP_3' => 'Si vous laissez ces champs vides, la synchronisation fonctionne toujours pour toutes les données (produits, stock, catégories, marques, clients, commandes) ; seul l\'ajout d\'images aux produits (recherche/téléversement) est ignoré.',
'Woo_Guide_How_To_Enable' => 'Comment activer',
'Woo_Guide_Enable_1' => 'Saisissez l\'URL de la boutique, la Consumer key et le Consumer secret ci-dessus, puis cliquez sur Enregistrer.',
'Woo_Guide_Enable_2' => 'Utilisez Tester la connexion pour vérifier les identifiants.',
'Woo_Guide_Enable_3' => 'Utilisez la synchronisation manuelle depuis n\'importe quel onglet lorsque vous avez besoin de synchroniser.',
'Woo_Guide_Enable_4' => 'Activez la Synchronisation automatique ci-dessus pour envoyer vers WooCommerce, au fur et à mesure, les produits nouveaux et modifiés ainsi que chaque changement de stock.',
'Woo_Guide_Manual_Sync' => 'Synchronisation manuelle (à la demande)',
'Woo_Guide_Manual_1' => 'La synchronisation fonctionne dans les deux sens : Stocky → WooCommerce et WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'La synchronisation manuelle est disponible dans tous les onglets WooCommerce (Produits, Stock, etc.) ; utilisez les actions de synchronisation de chaque onglet pour synchroniser à la demande.',
'Woo_Guide_Auto_1' => 'Produits : lorsque l\'option est activée, un produit que vous créez, modifiez ou dupliquez dans Stocky est envoyé à WooCommerce juste après son enregistrement, suivi de son stock.',
'Woo_Guide_Auto_2' => 'Stock : lorsque l\'option est activée, chaque changement de stock (vente POS, vente, retour, achat, ajustement, transfert) met à jour la quantité sur WooCommerce. Seuls les produits déjà liés à WooCommerce sont mis à jour.',
'Woo_Guide_Auto_3' => 'La synchronisation automatique envoie uniquement les modifications de Stocky vers WooCommerce. La récupération des données de WooCommerce vers Stocky (commandes, clients, produits) se fait toujours avec les boutons des onglets Commandes, Clients et Produits.',
'Woo_Guide_Auto_4' => 'Les imports de produits en masse ne sont pas envoyés automatiquement. Après un import, utilisez Synchroniser — POS → WooCommerce dans l\'onglet Produits.',
'Woo_Guide_Auto_5' => 'Chaque envoi automatique est enregistré dans l\'onglet Journaux : vous pouvez ainsi vérifier ce qui a été envoyé et repérer les erreurs.',
'Woo_Guide_First_Setup' => 'Première configuration',
'Woo_Guide_First_1' => 'Exécutez ces opérations une seule fois, dans cet ordre, pour lier votre catalogue existant : Synchroniser — POS → WooCommerce dans l\'onglet Catégories, puis dans l\'onglet Marque, puis dans l\'onglet Produits, et enfin Synchroniser le stock dans l\'onglet Stock. Ensuite, activez la Synchronisation automatique ci-dessus pour maintenir WooCommerce à jour.',
'Woo_Guide_First_2' => 'Les synchronisations volumineuses de produits et de stock s\'exécutent par petits lots et affichent leur progression dans l\'onglet. Gardez la page ouverte jusqu\'à la fin de la synchronisation ; vous pouvez l\'arrêter à tout moment.',
'Woo_Guide_First_3' => 'Si une synchronisation n\'avance plus pendant plusieurs minutes, consultez l\'onglet Journaux, puis contactez le support.',
'Woo_Guide_Notes_1' => 'Modifier l\'URL de la boutique ou les clés API réinitialise les correspondances (produits, catégories, marques, clients) ; les éléments seront de nouveau synchronisés vers la (nouvelle) boutique.',
'Woo_Guide_Notes_2' => 'Gardez des SKU cohérents entre Stocky et WooCommerce pour éviter les produits en double et pouvoir les relier à nouveau en toute sécurité.',
