'Pg_Credentials_Kept' => 'Vos identifiants sont conservés — la page de paiement de la boutique en ligne cesse simplement de proposer {name} jusqu\'à ce que vous le réactiviez.',
'Pg_Remove_Credentials_Confirm' => 'Supprimer les identifiants {name} enregistrés ? La page de paiement cessera de proposer {short}.',
