'Pg_Sandbox_Test_Mode' => 'Bac à sable (mode test)',
'Pg_Stripe_Shared_Notice' => 'Les clés Stripe sont partagées par l\'ensemble du système.',
'Pg_Store_Feature_Not_In_Plan' => 'Les passerelles de la boutique en ligne et les modes de paiement hors ligne font partie de la fonctionnalité Commandes en ligne, que votre plan actuel n\'inclut pas.',
'Pg_Intro_Title' => 'Chaque passerelle ci-dessous est proposée sur la page de paiement de la BOUTIQUE EN LIGNE dès que ses identifiants sont enregistrés et que son interrupteur est activé.',
'Pg_Intro_Desc' => 'Chaque onglet dispose de son propre interrupteur, enregistré dès que vous l\'actionnez : désactiver une passerelle conserve ses identifiants, la page de paiement cesse simplement de la proposer. Les clés Stripe sont partagées globalement (l\'administration et la boutique en ligne utilisent la même intégration Stripe). Paiements hors ligne regroupe le paiement à la livraison et le mobile money, qui sont réglés en dehors du système.',
'Pg_Label_Stripe_Key' => 'CLÉ STRIPE',
'Pg_Label_Stripe_Secret' => 'SECRET STRIPE',
'Pg_Card_Payments_Off' => 'Les paiements par carte sont désactivés',
'Pg_Card_Keys_Kept' => 'Vos clés sont conservées — la page de paiement de la boutique en ligne cesse simplement de proposer le paiement par carte jusqu\'à ce que vous le réactiviez.',
'Pg_No_Stripe_Key' => 'Aucune clé Stripe enregistrée',
'Pg_Enter_Stripe_Key' => 'Saisissez votre clé et votre secret Stripe pour commencer à accepter les paiements par carte dans la boutique en ligne.',
'Pg_Label_Razorpay_Key_Id' => 'RAZORPAY KEY ID',
'Pg_Label_Razorpay_Key_Secret' => 'RAZORPAY KEY SECRET',
'Pg_Razorpay_Help' => 'Utilise Razorpay Checkout sur la boutique (cartes, UPI, netbanking, portefeuilles). Le mode test ou live est déterminé par la paire de clés (rzp_test_/rzp_live_) — il n\'y a pas d\'interrupteur bac à sable distinct. La page de paiement propose Razorpay dès que les deux clés sont enregistrées.',
'Pg_Label_Bkash_App_Key' => 'BKASH APP KEY',
'Pg_Label_Bkash_App_Secret' => 'BKASH APP SECRET',
'Pg_Label_Bkash_Username' => 'NOM D\'UTILISATEUR BKASH',
'Pg_Label_Bkash_Password' => 'MOT DE PASSE BKASH',
'Pg_Bkash_Sandbox_Help' => 'ACTIVÉ utilise tokenized.sandbox.bka.sh avec vos identifiants bac à sable ; DÉSACTIVEZ pour débiter de vrais comptes bKash sur tokenized.pay.bka.sh.',
'Pg_Bkash_Help' => 'Utilise bKash Tokenized Checkout (identifiants marchand issus du portail marchand bKash). Débit en BDT. La page de paiement propose bKash dès que les quatre identifiants sont enregistrés.',
'Pg_Label_Sslcommerz_Store_Id' => 'SSLCOMMERZ STORE ID',
'Pg_Label_Sslcommerz_Store_Password' => 'SSLCOMMERZ STORE PASSWORD',
'Pg_Sslcommerz_Sandbox_Help' => 'ACTIVÉ utilise sandbox.sslcommerz.com avec des identifiants bac à sable ; DÉSACTIVEZ pour débiter de vrais clients sur securepay.sslcommerz.com.',
'Pg_Sslcommerz_Help' => 'Paiement hébergé couvrant les cartes, le mobile banking bKash/Nagad/Rocket et la banque en ligne au Bangladesh. Débit en BDT.',
'Pg_Sslcommerz_Ipn_Help' => 'URL IPN (filet de sécurité recommandé — à définir sous My Stores → IPN Settings dans le panneau marchand SSLCommerz) :',
'Pg_Label_Region' => 'RÉGION',
'Pg_Paymob_Region_Help' => 'Pays de votre compte Paymob : egypt, ksa, uae, pakistan ou oman (détermine l\'hôte de l\'API ; egypt par défaut).',
'Pg_Label_Public_Key' => 'CLÉ PUBLIQUE',
