'Shp_Never_Lc' => 'jamais',
'Shp_Auto_Off_Note' => 'Désactivé — ces étapes ne s\'exécutent que lorsque quelqu\'un clique sur Synchroniser.',
'Shp_Auto_On_Note' => 'Exécuté pour vous par le planificateur, toutes les cinq minutes — rien à installer. Une synchronisation manuelle compte comme une exécution : elle repousse la suivante de l\'intervalle de l\'étape.',
'Shp_Stock_Only_On_Push' => 'Le stock n\'atteint Shopify que lorsque l\'étape d\'envoi de l\'inventaire s\'exécute',
'Shp_Stock_Lag_Desc' => 'D\'ici là, une vente au comptoir reste invisible pour la boutique — jusqu\'à {n} minutes, si bien que la dernière unité peut encore être vendue deux fois en ligne. Activez {setting} et chaque vente, retour et ajustement est alors envoyé en quelques secondes.',
'Shp_Push_Stock_On_Change' => 'Envoyer le stock dès qu\'il change',
'Shp_Turn_It_On' => 'L\'activer',
'Shp_Instant_Push_Note' => 'Le stock est également envoyé quelques secondes après chaque vente, retour ou ajustement, sans attendre l\'une des étapes ci-dessus.',
'Shp_Sync_History' => 'Historique de synchronisation',
'Shp_Nothing_Run_For_Store' => 'Rien n\'a encore été exécuté pour cette boutique',
'Shp_Hook_Register_Cc' => 'Cliquez sur « Enregistrer les webhooks » ci-dessous — rien n\'est à saisir dans Shopify.',
'Shp_Hook_Register_Token' => 'Cliquez sur « Enregistrer les webhooks » ci-dessous, puis collez la clé secrète API (API secret key) de l\'application dans les paramètres de la boutique comme secret de signature.',
'Shp_Hook_Note_Register' => 'L\'enregistrement crée les abonnements dans Shopify et les fait pointer automatiquement vers cette adresse. Ne l\'ajoutez pas manuellement sous Shopify → Settings → Notifications → Webhooks : ceux-là sont signés avec un autre secret et chaque livraison serait refusée.',
'Shp_Hook_Verified_Cc' => 'Les livraisons sont vérifiées avec le client secret de l\'application, déjà enregistré.',
'Shp_Hook_Verified_Token' => 'Les livraisons sans signature valide sont refusées : le secret doit donc être défini avant que les webhooks ne fassent quoi que ce soit.',
'Shp_Hook_Retries' => 'Shopify réessaie jusqu\'à obtenir une réponse 2xx, et chaque livraison n\'est enregistrée qu\'une seule fois — un événement répété est sans effet et ne crée pas de commande en double.',
'Shp_No_Signing_Secret' => 'Aucun secret de signature enregistré',
'Shp_No_Signing_Secret_Desc' => 'Les abonnements peuvent être créés sans lui, mais chaque livraison sera refusée tant que la clé secrète API (API secret key) de l\'application n\'est pas enregistrée sur cette boutique (le client secret d\'une application Dev Dashboard couvre déjà ce point).',
'Shp_Register_In_Shopify' => 'Enregistrer dans Shopify',
