'Shp_Where_Data_Lands' => 'Destination des données',
'Shp_What_To_Sync' => 'Éléments à synchroniser',
'Shp_Name_Hint' => 'Nom de cette boutique dans l\'ERP',
'Shp_Name_Placeholder' => 'ex. Boutique principale',
'Shp_Domain_Hint' => '{domain} — l\'URL d\'administration fonctionne aussi',
'Shp_App_Credentials' => 'Identifiants de l\'application',
'Shp_Auth_Client_Credentials' => 'Client ID + client secret (application Dev Dashboard)',
'Shp_Auth_Token' => 'Jeton d\'accès Admin API (ancienne application personnalisée)',
'Shp_Cc_Alert' => 'Depuis janvier 2026, Shopify ne crée plus d\'applications personnalisées dans l\'administration. Créez l\'application dans le {dashboard}, accordez-lui ses portées Admin API, installez-la sur cette boutique, puis copiez le Client ID et le Client secret depuis sa page {settings}. L\'ERP obtient lui-même un nouveau jeton d\'accès toutes les 24 heures. L\'application et la boutique doivent appartenir à la même organisation Shopify.',
'Shp_Leave_Blank_Keep_Stored' => 'Laissez vide pour conserver la valeur enregistrée.',
'Shp_Client_Id_Placeholder' => 'Depuis la page Settings de l\'application',
'Shp_Client_Secret_Hint' => 'Signe également les webhooks : aucun secret de signature distinct n\'est nécessaire.',
'Shp_Masked_Unchanged' => '•••••••••••••• (inchangé)',
'Shp_Token_Keep_Hint' => 'Laissez vide pour conserver le jeton déjà enregistré.',
'Shp_Token_Legacy_Hint' => 'Uniquement pour les applications personnalisées créées dans l\'administration Shopify avant 2026 (Apps → Develop apps → API credentials). Les nouvelles applications n\'affichent pas de jeton ; utilisez plutôt le client ID + secret.',
'Shp_Webhook_Signing_Secret' => 'Secret de signature des webhooks',
'Shp_Webhook_Secret_Optional_Hint' => 'Facultatif ici — le client secret ci-dessus signe les webhooks d\'une application Dev Dashboard.',
'Shp_Webhook_Secret_Required_Hint' => 'Obligatoire avant que les webhooks soient acceptés — les livraisons non signées sont refusées.',
'Shp_Will_Be_Cleared' => 'Sera effacé à l\'enregistrement',
'Shp_Clear_Stored_Secret' => 'Effacer le secret enregistré',
'Shp_Keep_It' => 'Finalement, le conserver',
'Shp_Domain_Locked' => 'Le domaine est verrouillé, car le modifier invalide toutes les correspondances de cette boutique.',
'Shp_Change_Anyway' => 'Le modifier quand même',
'Shp_Domain_Change_Warning' => 'Enregistrer un autre domaine supprime toutes les correspondances d\'enregistrements de cette connexion — les ID enregistrés appartiennent à l\'ancienne boutique.',
'Shp_ERP_Warehouse' => 'Entrepôt ERP',
'Shp_ERP_Warehouse_Hint' => 'Les niveaux de stock et les commandes importées sont rattachés à cet entrepôt.',
'Shp_Available_After_Connecting' => 'Disponible après la connexion',
'Shp_Fetch_Locations' => 'Récupérer les emplacements depuis Shopify',
'Shp_Price_Sent' => 'Prix envoyé à Shopify',
'Shp_Create_Missing_Products' => 'Créer des produits ERP pour les produits Shopify sans SKU correspondant',
'Shp_Create_Missing_Customers' => 'Créer des clients ERP pour les clients Shopify sans e-mail correspondant',
'Shp_Create_Missing_Customers_Hint' => 'Si cette option est désactivée, une commande d\'un client inconnu est ignorée plutôt que devinée.',
'Shp_Entities_Lead' => 'Seules les entités activées ici peuvent être synchronisées — une boutique dont vous ne faites que récupérer les commandes ne doit pas voir son catalogue réécrit par un envoi de produits intempestif.',
'Shp_Sync_On_Schedule' => 'Synchroniser automatiquement selon une planification',
'Shp_Scheduler_Hint' => 'Le planificateur vérifie toutes les 5 minutes, ce qui est la granularité la plus fine utilisable par les intervalles ci-dessous. Les synchronisations peuvent toujours être lancées manuellement.',
'Shp_Instant_Push_Hint' => 'Une vente, un retour ou un ajustement envoie le stock des seuls produits concernés dès son enregistrement, si bien que la boutique est à jour en quelques secondes au lieu d\'attendre la prochaine exécution planifiée. Rien d\'autre à installer — l\'envoi s\'exécute une fois la vente traitée, la caisse n\'attend donc jamais Shopify.',
'Shp_Switch_Inventory_First' => 'Activez d\'abord Inventaire sous {tab}.',
'Shp_Leave_Off_Lag' => 'Si vous laissez cette option désactivée, une vente POS n\'atteint Shopify qu\'au prochain envoi de l\'inventaire — jusqu\'à {n} minutes plus tard.',
'Shp_Default_Interval' => 'Intervalle par défaut (minutes)',
'Shp_Default_Interval_Hint' => 'Utilisé par toutes les étapes qui ne définissent pas le leur.',
'Shp_What_Runs_Auto' => 'Ce qui s\'exécute automatiquement',
'Shp_Plan_Hint' => 'Chaque étape correspond à une entité dans un sens. Les commandes proviennent toujours uniquement {from} Shopify.',
'Shp_From' => 'de',
'Shp_Add_Step' => 'Ajouter une étape',
'Shp_Using_Default_Plan' => 'Plan par défaut utilisé',
'Shp_Default_Plan_Desc' => 'Les commandes sont récupérées et le stock est envoyé toutes les {n} minutes. Ajoutez une étape pour définir votre propre plan — vider à nouveau la liste rétablit ce plan par défaut.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} est désactivé dans l\'onglet précédent — cette étape sera ignorée.',
'Shp_Inactive_Lc' => 'inactif',
'Shp_No_Locations' => 'Cette boutique ne signale aucun emplacement',
'Shp_Could_Not_Load_Locations' => 'Impossible de charger les emplacements — vérifiez d\'abord la connexion',
'Shp_Store_Updated' => 'Boutique mise à jour',
'Shp_Store_Connected' => 'Boutique connectée',
'Shp_Could_Not_Save_Store' => 'Impossible d\'enregistrer cette boutique',
'Shp_G_Lead_Store' => 'Ce dont cette boutique a besoin pour rester synchronisée. Tout ce qui figure ici est propre à cette boutique — l\'URL du webhook et les ID sont réels.',
'Shp_G_Lead_Store_Cmd' => 'Ce dont cette boutique a besoin pour rester synchronisée. Tout ce qui figure ici est propre à cette boutique — l\'URL du webhook et les ID sont réels, les commandes peuvent donc être copiées telles quelles sur le serveur.',
'Shp_G_Lead_Generic' => 'Comment une boutique Shopify reste synchronisée avec l\'ERP. Choisissez une boutique ci-dessus pour voir son propre état, ou lisez ce guide tel quel — l\'URL du webhook est la même quelle que soit la boutique connectée.',
'Shp_G_Lead_Generic_Cron' => 'Comment une boutique Shopify reste synchronisée avec l\'ERP. Choisissez une boutique ci-dessus pour voir son propre état, ou lisez ce guide tel quel — l\'URL du webhook et la ligne cron sont les mêmes quelle que soit la boutique connectée.',
'Shp_G_Ways_Note' => 'La plupart des boutiques utilisent les deux : la première maintient la boutique à jour minute par minute, la seconde rattrape tout ce que la première a manqué — un webhook jamais arrivé, une modification faite directement dans l\'administration Shopify, une nuit où le site était hors ligne.',
'Shp_G_Both_Need' => 'Les deux méthodes nécessitent d\'abord ceci',
'Shp_G_Credentials' => 'Identifiants Shopify',
'Shp_G_Cred_Intro' => 'Depuis janvier 2026, Shopify ne crée plus d\'applications personnalisées dans l\'administration ; il existe donc deux types de connexion :',
'Shp_G_Cred_Dev' => '{app} (toute boutique connectée aujourd\'hui) — {path}. Accordez les portées Admin API correspondant à ce que cette boutique synchronise, installez l\'application sur la boutique, puis copiez le {clientId} et le {clientSecret} depuis la page Settings de l\'application dans {edit}. L\'ERP les échange lui-même contre un jeton d\'accès et le renouvelle avant son expiration, toutes les 24 heures. Le client secret signe également les webhooks : rien d\'autre n\'est nécessaire. L\'application et la boutique doivent appartenir à la même organisation Shopify.',
'Shp_G_Dev_App' => 'Application Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (créée dans l\'administration avant 2026) — continue de fonctionner sans changement avec son {token} ({prefix}) et sa {secret} comme secret de signature des webhooks. Ce n\'est pas la même valeur que le jeton, et les intervertir est la cause habituelle des webhooks refusés.',
'Shp_G_Legacy_App' => 'Ancienne application personnalisée',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'enregistré',
'Shp_G_Missing_Refused' => 'manquant — les livraisons seront refusées',
'Shp_G_Targets' => '{path} L\'entrepôt ERP dont cette boutique vend le stock, et l\'emplacement Shopify dans lequel ce stock est écrit. La synchronisation de l\'inventaire et l\'import des commandes refusent tous deux de s\'exécuter sans eux.',
'Shp_G_Currently' => 'Actuellement : entrepôt {warehouse}, emplacement {location}',
'Shp_G_Not_Set_Lc' => 'non défini',
'Shp_G_Ready' => 'prêt',
'Shp_G_Incomplete' => 'incomplet',
'Shp_G_Manual_Syncs' => 'Synchronisations lancées manuellement',
'Shp_G_Manual_Body' => 'Une synchronisation lancée depuis le {centre} répond immédiatement et s\'exécute en arrière-plan, par courtes tranches qui reprennent chacune là où la précédente s\'est arrêtée. Un gros catalogue n\'est jamais interrompu en cours de route par une requête web arrivée à expiration, et fermer la page ne l\'arrête pas.',
'Shp_G_Worker_Managed' => 'Votre plateforme exécute le worker nécessaire : il n\'y a rien à installer.',
'Shp_G_Worker_Cron' => 'Le worker nécessaire tient en une ligne cron supplémentaire :',
'Shp_G_Cron_Copied' => 'Ligne cron copiée',
'Shp_G_Worker_Busy' => 'Si le worker est occupé, la page du Centre de synchronisation ouverte poursuit elle-même l\'exécution au bout de quelques secondes, une courte requête à la fois — une synchronisation se termine donc toujours sous vos yeux.',
'Shp_G_Pick_How' => 'Choisissez ensuite comment elle reste synchronisée',
'Shp_G_Right_Away' => 'Immédiatement',
'Shp_G_Stock_Live' => 'stock en temps réel',
'Shp_G_Stock_Not_Live' => 'stock pas en temps réel',
'Shp_G_Realtime_Lead' => 'Chaque modification est envoyée au moment où elle se produit, en quelques secondes. Deux moitiés, commandées par deux interrupteurs distincts : les {webhooks} font entrer les événements propres à la boutique, et l\'{push} fait sortir le stock.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'envoi instantané du stock',
'Shp_G_Webhooks_Heading' => 'Webhooks — de la boutique → vers l\'ERP',
'Shp_G_Webhooks_Body' => 'Les commandes, les changements de statut des commandes, ainsi que les modifications de produits, de clients et de stock faites dans Shopify. Ouvrez la boutique et cliquez sur {button} dans son {tab} — sans risque si vous cliquez deux fois. Shopify envoie à :',
'Shp_G_Webhooks_Tab' => 'onglet Webhooks',
'Shp_G_Webhooks_Note' => 'L\'adresse doit être accessible depuis Internet en HTTPS — Shopify ne livre ni à {localhost} ni à un domaine {test}. Chaque livraison n\'est enregistrée qu\'une fois : les nouvelles tentatives de Shopify ne peuvent donc pas créer de commande en double, et une livraison échouée peut être rejouée. Les livraisons sont refusées tant que le secret de signature de l\'étape 1 n\'est pas enregistré.',
'Shp_G_Push_Heading' => 'Envoi instantané du stock — de l\'ERP → vers la boutique',
'Shp_G_People_Miss' => 'C\'est le paramètre que l\'on oublie',
'Shp_G_Push_P1' => 'Une vente POS n\'atteint {not} Shopify d\'elle-même. Si l\'option est désactivée, la boutique ne l\'apprend qu\'à la prochaine étape d\'envoi de l\'inventaire — et dans cet intervalle, elle peut vendre une unité déjà vendue en caisse.',
'Shp_G_Not' => 'pas',
'Shp_G_Push_P2' => 'Cochez {setting} dans {path}. C\'est toute la configuration — ni worker, ni cron. Chaque vente, retour et ajustement envoie alors le stock des seuls produits concernés, juste après l\'enregistrement de la vente, et une vente de vingt lignes ne coûte qu\'un seul envoi, pas vingt. La caisse ne l\'attend jamais.',
'Shp_G_This_Store' => 'Cette boutique :',
'Shp_G_Push_On' => 'activé — stock envoyé à chaque modification',
'Shp_G_Push_Off' => 'désactivé — stock uniquement selon la planification',
'Shp_G_Push_Note' => 'Seuls les produits déjà mis en correspondance avec Shopify, et seuls les mouvements dans l\'entrepôt de cette boutique, sont envoyés. Les opérations en masse — supprimer un produit, réinitialiser un entrepôt — écrivent le stock sans déclencher d\'événement, ce qui est une raison de conserver aussi l\'étape d\'inventaire planifiée.',
'Shp_G_Nothing_Else' => 'Rien d\'autre à installer',
'Shp_G_Nothing_Else_Body' => 'Aucune des deux moitiés n\'a besoin d\'un worker de file d\'attente ni d\'une entrée cron. Un webhook entrant est traité dans la requête envoyée par Shopify ; un envoi de stock sortant s\'exécute dans le même processus que celui qui a traité la vente, {after} le renvoi de la réponse — la caisse n\'attend donc jamais Shopify, et une boutique qui ne répond plus est abandonnée au bout de dix secondes et laissée au prochain envoi d\'inventaire planifié.',
'Shp_G_After' => 'après',
'Shp_G_Exception' => 'Une exception : une modification de stock effectuée par une tâche d\'arrière-plan n\'a pas de réponse après laquelle s\'exécuter ; elle est donc placée dans la file {queue}.',
'Shp_G_Queue_Managed' => 'Votre plateforme exécute déjà un worker sur cette file : ces envois partent donc aussi d\'eux-mêmes.',
'Shp_G_Queue_Cron' => 'Si vous voulez que ces envois partent aussi rapidement, videz cette file :',
'Shp_G_On_Schedule' => 'Selon une planification',
'Shp_G_On_Lc' => 'activé',
'Shp_G_Off_Lc' => 'désactivé',
'Shp_G_Scheduled_Lead' => 'Tout est revérifié régulièrement, dans les deux sens. Plus lent que le temps réel, mais c\'est ce qui envoie le stock pour les boutiques qui n\'utilisent pas l\'envoi instantané, ce qui rattrape un webhook manqué, et le seul moyen de transférer un catalogue entier.',
'Shp_G_Nothing_To_Install' => 'Rien à installer',
'Shp_G_Managed_Body' => 'Le planificateur est exécuté pour vous : toutes les cinq minutes, votre plateforme demande à chaque boutique si une étape de son plan est due, et exécute celles qui le sont. Aucune entrée cron à ajouter, aucun serveur à maintenir.',
'Shp_G_Managed_Note' => 'Cinq minutes est aussi la granularité la plus fine utilisable par un plan, car c\'est l\'intervalle d\'étape le plus court. Les intervalles plus longs sont respectés exactement — une étape réglée sur 30 minutes est vérifiée six fois et s\'exécute une fois.',
'Shp_G_Cron_Entry' => 'L\'entrée cron',
'Shp_G_Cron_Body' => 'Rien de planifié ne s\'exécute sans elle. Une seule ligne, pour ce module uniquement — ajoutez-la à côté de tout ce que vous avez choisi de planifier par ailleurs :',
'Shp_G_Cron_Note' => 'Toutes les cinq minutes est la granularité la plus fine utilisable par un plan, car cinq minutes est l\'intervalle d\'étape le plus court. Une entrée moins fréquente devient simplement le plancher — avec {every15}, une étape réglée sur 5 minutes s\'exécute toutes les 15. Sous Windows, utilisez le Planificateur de tâches : programme {php}, arguments {args}, démarrer dans {path}.',
'Shp_G_Switch_On' => 'Activez-la et choisissez le plan',
'Shp_G_Plan_Body' => '{path} L\'interrupteur décide si le planificateur peut agir ; le plan décide de ce qu\'il fait. Une {step} correspond à une entité dans un sens avec son propre intervalle — {ex1}, {ex2}. L\'intervalle par défaut s\'applique à toute étape dont le champ reste vide.',
'Shp_G_Step_Lc' => 'étape',
'Shp_G_Ex1' => 'Commandes · Shopify → ERP toutes les 15 min',
'Shp_G_Ex2' => 'Inventaire · ERP → Shopify toutes les 30 min',
'Shp_G_Plan_Note' => 'Laissez le plan vide et la boutique récupère les commandes et envoie le stock à l\'intervalle par défaut, ce que veulent la plupart des boutiques. Les commandes sont en récupération seule : c\'est dans Shopify que le client passe commande.',
'Shp_G_Schedule_On' => 'planification activée',
'Shp_G_Schedule_Off' => 'planification désactivée — manuel uniquement',
'Shp_G_When_Runs' => 'Quand une étape s\'exécute réellement',
'Shp_G_When_Body' => 'Une étape est due lorsque son dernier {started} remonte à plus longtemps que son intervalle, d\'après l\'historique des exécutions. Une synchronisation lancée manuellement repousse donc la prochaine exécution automatique, et une étape qui échoue sans cesse est retentée selon son intervalle plutôt qu\'à chaque cycle. La vue d\'ensemble de la boutique indique pour chaque étape sa dernière exécution, sa prochaine échéance et, le cas échéant, la raison de son blocage. Lancez le premier envoi du catalogue manuellement depuis le Centre de synchronisation — d\'abord en simulation — avant de le planifier.',
'Shp_G_Started_Lc' => 'démarrage',
'Shp_G_Where_Setting' => 'Où se trouve chaque paramètre',
'Shp_G_Where_Note' => 'Tous se trouvent sur une boutique existante : {path}, puis le crayon (ou {edit} sur la page de la boutique).',
'Shp_G_Product_Images' => 'Images des produits',
'Shp_G_Img1' => 'Les images partent avec le produit lors d\'un {push} — l\'image principale d\'abord, puis la galerie, puis une par variante qui possède la sienne, jusqu\'à cinquante.',
'Shp_G_Products_Push' => 'envoi des produits',
'Shp_G_Img2' => 'L\'image d\'une variante est téléversée avec le produit puis {assigned}, ce qui correspond au modèle de Shopify : une variante pointe vers l\'une des images du produit. Une variante qui réutilise l\'image principale ne la téléverse pas deux fois.',
'Shp_G_Assigned' => 'attribuée à cette variante',
'Shp_G_Img3' => 'Une image stockée sous forme de fichier est {uploaded} vers Shopify, et non liée : cela fonctionne donc même lorsque cette installation n\'est pas accessible depuis Internet. Une image ajoutée sous forme de lien collé est transmise à Shopify sous cette URL, qui doit être accessible publiquement.',
'Shp_G_Uploaded' => 'téléversée',
'Shp_G_Img4' => 'Elles ne sont renvoyées que lorsqu\'elles changent réellement — un envoi qui ne modifie qu\'un prix ne touche pas aux images de la boutique, car les envoyer remplace l\'ensemble.',
