'Agt_Series' => 'Séries',
'Agt_Series_Hint' => 'L’AGT autorise une série de numérotation par type de document, année et établissement. Les factures ne peuvent pas être émises sans série active pour leur type et leur année.',
'Agt_Request_Series' => 'Demander une série à l’AGT',
