'Agt_Correct_Confirm' => 'Émettre une correction avec un nouveau numéro pour ce document rejeté ?',
'Agt_Correct' => 'Corriger',
'Agt_Guide_What_Title' => 'À quoi cela sert',
'Agt_Guide_What_Body' => 'Chaque vente finalisée est émise en tant que facture électronique AGT (FR si payée à la création, sinon FT) et chaque retour reçu en tant que note de crédit (NC). Chaque document reçoit le numéro suivant de sa série AGT, est signé avec votre clé AGT et envoyé à l’AGT, qui le valide quelques minutes plus tard. Le reçu et la facture PDF impriment le numéro AGT, l’extrait de sécurité et un code QR.',
'Agt_Guide_Steps_Title' => 'Configuration',
'Agt_Guide_Step_1' => 'Adhérez à la facturation électronique (adesão) sur le Portal do Contribuinte et téléchargez votre clé privée AGT.',
'Agt_Guide_Step_2' => 'Saisissez votre NIF, votre établissement et la clé dans l\'onglet Configuration, choisissez Homologação, enregistrez puis utilisez Tester la connexion.',
'Agt_Guide_Step_3' => 'Dans l\'onglet Séries, demandez une série par type de document utilisé (FR, FT, NC) pour l\'année en cours.',
'Agt_Guide_Step_4' => 'Associez vos taux d\'IVA aux codes AGT et définissez le code d\'exonération pour les lignes à 0 %.',
'Agt_Guide_Step_5' => 'Activez le module dans Paramètres du système > Fonctionnalités, effectuez une vente test et vérifiez qu\'elle devient valide dans l\'onglet Documents.',
'Agt_Guide_Step_6' => 'Lorsque l\'AGT vous autorise à passer en production, basculez sur Produção et demandez des séries de production.',
'Agt_Guide_Note_1' => 'Une vente ou un retour déjà communiqué ne peut plus être modifié ni supprimé. Corrigez-le au moyen d\'un retour de vente (avoir).',
'Agt_Guide_Note_2' => 'Les documents rejetés par l\'AGT sont corrigés avec un nouveau numéro qui fait référence au document rejeté ; l\'ancien numéro n\'est jamais réutilisé.',
'Agt_Guide_Note_3' => 'Les ventes POS hors ligne sont communiquées lors de leur synchronisation. L\'AGT pénalise les documents envoyés avec plus de 24 heures de retard.',
'Agt_Guide_Note_4' => 'Une ligne ne peut pas porter à la fois une taxe produit et la taxe de la commande ; l\'AGT exige un seul taux d\'IVA par ligne. La livraison est envoyée comme ligne exonérée.',
'Agt_Guide_Note_5' => 'Les totaux AGT sont calculés par ligne et peuvent différer du total Stocky de quelques centimes d\'arrondi.',
