'Dgi_Guide_What_Title' => 'Ce que fait le module aujourd\'hui',
'Dgi_Guide_What_Body' => 'Lorsque le module est activé, les reçus et les factures PDF impriment le NIF, le RCCM et l\'Id. Nat. du vendeur exigés sur la facture normalisée. La certification complète (numéro DEF, compteurs, code d\'authentification et QR renvoyés par la DGI) sera ajoutée dès que l\'API développeur de l\'e-MCF sera connectée.',
'Dgi_Guide_Steps_Title' => 'Obtenir l\'accès à l\'e-MCF',
