'Comm_G_Step_Rule' => 'Ajouter au moins une règle',
'Comm_G_Step_Rule_Help' => 'Une règle indique combien payer, par exemple 5 % du total de la vente. Elle doit être Active et appartenir à un programme actif aujourd\'hui.',
'Comm_G_Step_Rule_Warn' => 'Vous avez des règles, mais aucune n\'est active dans un programme actif aujourd\'hui.',
'Comm_G_Step_Sale' => 'Réaliser une vente terminée',
'Comm_G_Step_Sale_Help' => 'Les commissions sont créées lorsqu\'une vente terminée est enregistrée (Ajouter une vente, Modifier la vente ou POS). Les ventes réalisées avant la création de vos règles ne sont pas calculées.',
'Comm_G_Step_Sale_Done' => '{n} commission(s) calculée(s) jusqu\'à présent.',
'Comm_G_Step_Approve' => 'Approuver les commissions',
'Comm_G_Step_Approve_Help' => 'Dans le Rapport de commissions, cochez les lignes En attente que vous validez et cliquez sur Approuvé. Rien n\'est en attente pour le moment.',
'Comm_G_Step_Approve_Warn' => '{n} commission(s) en attente d\'approbation.',
'Comm_G_Step_Pay' => 'Payer vos commerciaux',
'Comm_G_Step_Pay_Help' => 'Dans Reçus de commission, choisissez un commercial, cochez ses commissions Approuvées et enregistrez le reçu. Elles passent à l\'état Payée. Rien n\'est en attente de paiement pour le moment.',
'Comm_G_Step_Pay_Warn' => '{n} commission(s) approuvée(s) en attente de paiement.',
'Comm_G_Try_Rule' => 'Tester une règle',
'Comm_G_Try_Rule_Help' => 'Saisissez une vente et une règle pour voir exactement ce que la règle paierait. Le calcul est le même que celui utilisé par le système.',
'Comm_G_Sale_Total' => 'Total de la vente',
'Comm_G_None' => 'Aucun',
'Comm_G_Commission' => 'Commission pour cette règle',
'Comm_G_No_Commission' => 'Aucune commission',
'Comm_G_Calc_Base' => 'Montant de base ({source}) : {base}',
'Comm_G_Calc_Zero_Base' => 'Le montant de base est de 0 : cette règle ne crée donc rien. Avec Montant payé comme source, une vente impayée ne rapporte rien tant qu\'aucun paiement n\'est enregistré.',
'Comm_G_Calc_Below_Min' => 'La base est inférieure au seuil minimum de {min} : cette règle ne crée donc rien pour cette vente.',
'Comm_G_Calc_Pct' => '{value} % de {base} = {amount}',
'Comm_G_Calc_Fixed' => 'Montant fixe : {amount} par vente, quel que soit le montant de la vente',
'Comm_G_Calc_Capped' => 'Supérieur au plafond maximum, il est donc ramené à {cap}',
'Comm_G_Calc_Zero' => 'Le résultat est 0, aucune commission n\'est donc créée.',
'Comm_G_The_Flow' => 'Le processus, étape par étape',
'Comm_G_Flow_Program' => 'Programme',
'Comm_G_Flow_Program_Help' => 'Créez un programme et définissez ses dates de validité.',
'Comm_G_Flow_Agent' => 'Commerciaux',
'Comm_G_Flow_Agent_Help' => 'Ajoutez les personnes qui perçoivent une commission et liez les membres du personnel à leurs comptes utilisateurs.',
'Comm_G_Flow_Rule' => 'Règles',
'Comm_G_Flow_Rule_Help' => 'Dans le programme, ajoutez des règles : en pourcentage ou fixes, pour tous les commerciaux ou un seul.',
'Comm_G_Flow_Sale' => 'Vente',
'Comm_G_Flow_Sale_Help' => 'Une vente terminée est enregistrée. Chaque règle correspondante crée une commission En attente.',
'Comm_G_Flow_Approve' => 'Approuver',
'Comm_G_Flow_Approve_Help' => 'Examinez les commissions En attente dans le Rapport de commissions, puis approuvez-les ou annulez-les.',
'Comm_G_Flow_Pay' => 'Payer',
'Comm_G_Flow_Pay_Help' => 'Enregistrez un Reçu de commission pour le commercial. Les commissions qu\'il couvre passent à l\'état Payée.',
'Comm_G_How_It_Works' => 'Fonctionnement',
'Comm_G_T_Credit' => 'Quel commercial perçoit la commission ?',
'Comm_G_Credit_Intro' => 'Chaque vente est attribuée à un seul commercial au maximum. Le système vérifie, dans cet ordre :',
'Comm_G_Credit_Picked' => 'Le commercial choisi sur la vente : le champ Commercial dans Ajouter une vente et Modifier la vente, ou le bouton « Vendu par » sur le POS. Si ce commercial a été désactivé depuis, la vente ne rapporte rien ; le système ne passe pas aux options suivantes.',
'Comm_G_Credit_Seller' => 'Sinon, le commercial lié au vendeur choisi sur le POS (lorsque l\'option vendeur du POS est activée).',
'Comm_G_Credit_Cashier' => 'Sinon, le commercial lié à l\'utilisateur qui a enregistré la vente.',
'Comm_G_Credit_Nobody' => 'Si aucune de ces options ne trouve de commercial actif, la vente ne génère aucune commission.',
'Comm_G_Credit_Note' => 'Sur le POS, laisser le commercial sur « Automatique » utilise les options 2 et 3. Le nom affiché à côté de « Automatique » est celui du commercial qui sera crédité.',
'Comm_G_T_When' => 'Quand les commissions sont-elles calculées et mises à jour ?',
'Comm_G_When_Intro' => 'Les commissions sont créées pour la première fois lorsqu\'une vente au statut Terminée est enregistrée, à l\'un de ces endroits :',
'Comm_G_When_Create' => 'Ajouter une vente : lorsque la vente est enregistrée comme Terminée.',
'Comm_G_When_Edit' => 'Modifier la vente : enregistrer une vente Terminée la recalcule entièrement avec son total, ses paiements et son commercial actuels, y compris les commissions qui avaient été annulées.',
'Comm_G_When_Pos' => 'POS : lorsqu\'une vente est terminée, y compris un brouillon terminé ultérieurement.',
'Comm_G_When_Payment' => 'Ajout d\'un paiement à une vente Terminée, ce qui permet aux règles Montant payé de prendre en compte les paiements encaissés après la vente.',
'Comm_G_When_Cod' => 'Paiement à la livraison par transporteur : lorsque l\'argent encaissé par le transporteur est enregistré comme paiement sur la vente.',
'Comm_G_When_Not_Intro' => 'Les éléments suivants NE créent PAS de commissions :',
'Comm_G_When_Not_Status' => 'Les ventes enregistrées En attente ou Commandée. Elles commencent à générer des commissions une fois modifiées et enregistrées comme Terminée.',
'Comm_G_When_Not_Before' => 'Les ventes enregistrées avant l\'existence du programme ou de la règle. Elles ne sont pas calculées en arrière-plan. Ouvrir une telle vente dans Modifier la vente et l\'enregistrer la calcule avec les règles actives à la date de la vente.',
'Comm_G_When_Not_Import' => 'Les ventes importées depuis un fichier.',
'Comm_G_When_Not_Online' => 'Les commandes passées sur la boutique en ligne.',
'Comm_G_T_Statuses' => 'Statuts des commissions',
'Comm_G_Meaning' => 'Signification',
'Comm_G_S_Pending' => 'Tout juste calculée à partir d\'une vente. Personne ne l\'a encore vérifiée. Approuvez-la ou annulez-la dans le Rapport de commissions.',
'Comm_G_S_Approved' => 'Vérifiée et validée. Elle est due au commercial et peut être incluse dans un Reçu de commission. Si la vente change et que le montant varie, elle repasse En attente pour un nouvel examen.',
'Comm_G_S_Paid' => 'Incluse dans un Reçu de commission. Définitif : les commissions payées ne sont jamais modifiées. Si la vente change ensuite, la différence est ajoutée sous forme d\'Ajustement distinct.',
'Comm_G_S_Cancelled' => 'Ne sera pas payée. Elle reste annulée même si des paiements ou des retours arrivent plus tard. Enregistrer la vente dans Modifier la vente, ou la cocher dans le rapport et cliquer sur Recalculer, la recalcule.',
'Comm_G_Field' => 'Champ',
'Comm_G_T_Programs' => 'Programmes de commission',
'Comm_G_Programs_Body' => 'Un programme est un conteneur de règles, généralement un par période ou par campagne. Une règle ne fonctionne que lorsque son programme est Actif et que la date de la vente est comprise dans les dates du programme. Plusieurs programmes peuvent être actifs en même temps, et ils s\'appliquent tous.',
'Comm_G_F_Program_Name' => 'Tout nom qui vous aide à reconnaître le programme, par exemple « T4 2026 » ou « Black Friday ».',
'Comm_G_F_Program_Active' => 'Décochez-la pour suspendre d\'un coup toutes les règles du programme. Les commissions déjà créées ne sont pas affectées.',
'Comm_G_F_Program_From' => 'Les ventes datées d\'avant ce jour sont ignorées par le programme. Laissez vide pour ne pas fixer de date de début.',
'Comm_G_F_Program_To' => 'Les ventes datées d\'après ce jour sont ignorées par le programme. Laissez vide pour un programme sans date de fin.',
'Comm_G_T_Agents' => 'Commerciaux',
'Comm_G_Agents_Body' => 'Un commercial est la personne qui perçoit la commission. Il n\'a pas besoin d\'être utilisateur du système : des apporteurs d\'affaires ou des revendeurs externes peuvent aussi être commerciaux, et ils perçoivent une commission chaque fois qu\'ils sont choisis sur une vente.',
'Comm_G_F_Agent_Name' => 'Le nom affiché sur les ventes, le rapport et les reçus.',
'Comm_G_F_Agent_Code' => 'Référence facultative, comme un matricule. Permet la recherche dans la liste des commerciaux.',
'Comm_G_F_Agent_User' => 'Lie le commercial à un utilisateur du personnel. Les ventes réalisées par cet utilisateur (ou pour lesquelles il est choisi comme vendeur sur le POS) sont alors automatiquement attribuées à ce commercial.',
'Comm_G_F_Agent_Active' => 'Les commerciaux inactifs ne perçoivent rien sur les nouvelles ventes et disparaissent des sélecteurs de commerciaux. Leurs commissions passées sont conservées.',
'Comm_G_T_Rules' => 'Règles de commission : chaque champ expliqué',
'Comm_G_Rules_Body' => 'Une règle détermine le montant payé sur une vente. Utilisez l\'encadré « Tester une règle » ci-dessus pour vérifier une règle avant de l\'enregistrer.',
'Comm_G_F_Rule_Program' => 'Le programme auquel appartient la règle. La règle ne fonctionne que lorsque ce programme est actif et dans ses dates de validité.',
'Comm_G_F_Rule_Type' => 'Pourcentage paie une part du montant de base. Fixe paie le même montant sur chaque vente éligible, quel que soit son montant.',
'Comm_G_F_Rule_Source' => 'Ce sur quoi le pourcentage est calculé. Total de la vente correspond au total général de la vente. Montant payé correspond à ce que le client avait payé au moment du calcul de la commission.',
'Comm_G_F_Rule_Value' => 'Le pourcentage (5 signifie 5 %) ou le montant fixe, selon le Type.',
'Comm_G_F_Rule_Min' => 'Facultatif. Les ventes dont le montant de base est inférieur à ce seuil ne rapportent rien avec cette règle. Une vente exactement égale au seuil rapporte bien une commission.',
'Comm_G_F_Rule_Cap' => 'Facultatif. Le montant maximum que cette règle peut payer sur une vente. Fonctionne pour les règles en pourcentage comme pour les règles fixes.',
'Comm_G_F_Rule_Applies' => 'Tous les commerciaux : chaque commercial perçoit une commission avec cette règle. Commercial spécifique : uniquement le commercial sélectionné. Une règle Commercial spécifique sans commercial sélectionné ne paie jamais personne.',
'Comm_G_F_Rule_Priority' => 'Dans un programme réglé sur « Seule la règle la plus prioritaire paie », la règle éligible ayant le nombre le plus élevé l\'emporte et les autres sont ignorées. En cas d\'égalité, une règle Commercial spécifique l\'emporte sur une règle Tous les commerciaux. Dans un programme réglé sur « Toutes les règles correspondantes paient », la Priorité ne définit que l\'ordre.',
'Comm_G_F_Rule_Active' => 'Décochez-la pour suspendre cette seule règle. Les commissions qu\'elle a déjà créées ne sont pas affectées.',
'Comm_G_T_Stacking' => 'Plusieurs règles sur une même vente',
'Comm_G_Stacking_Body' => 'Chaque programme décide comment ses règles se combinent (le paramètre « Lorsque plusieurs règles correspondent » du programme).

Seule la règle la plus prioritaire paie (par défaut pour les nouveaux programmes) : les règles sont essayées de la Priorité la plus élevée à la plus basse, et la première éligible pour la vente paie. Une règle est éligible lorsque la vente atteint son seuil minimum et que le résultat est supérieur à 0. Cela facilite les paliers : « 7 % sur les ventes de 10,000 ou plus » en priorité 10 et « 5 % » en priorité 0. Pour accorder un taux spécial à Sara, ajoutez pour elle une règle Commercial spécifique avec une priorité supérieure à celle de la règle Tous les commerciaux.

Toutes les règles correspondantes paient : toutes les règles correspondantes paient et les montants s\'additionnent. Une règle Tous les commerciaux de 3 % plus une règle Commercial spécifique de 2 % pour Sara donnent 5 % à Sara.

Les programmes sont indépendants les uns des autres : chaque programme actif paie de son côté, de sorte qu\'une vente peut rapporter à la fois au titre d\'un programme de base et d\'un programme de campagne.',
'Comm_G_T_Paying' => 'Payer les commerciaux avec des Reçus de commission',
'Comm_G_Paying_Body' => 'Ouvrez Reçus de commission et cliquez sur Ajouter. Choisissez le commercial : ses commissions Approuvées s\'affichent. Cochez celles que vous payez ; le Montant se remplit avec leur total, et vous pouvez l\'ajuster. La Référence est renseignée automatiquement (CR-000001, CR-000002...), et vous pouvez ajouter le mode de paiement, la date et une note.

L\'enregistrement du reçu passe les commissions cochées à l\'état Payée et les lie au reçu. Seules les commissions Approuvées peuvent être payées : approuvez-les donc d\'abord dans le Rapport de commissions.

Les Ajustements négatifs (sommes versées en trop au commercial) sont également listés. Cochez-les avec les prochaines commissions du commercial afin qu\'ils soient déduits de ce paiement.

Un reçu n\'est qu\'un enregistrement du versement : il ne crée pas de dépense et ne déplace pas d\'argent dans vos comptes. Si vous suivez les versements dans Dépenses ou Comptabilité, enregistrez-les également là.',
'Comm_G_T_Snapshot' => 'Lorsqu\'une vente change',
'Comm_G_Snapshot_Body' => 'Les commissions suivent la vente. Chaque fois qu\'une vente comportant des commissions change, celles-ci sont recalculées à partir de ses chiffres actuels : le total de la vente moins les retours reçus, et le montant payé moins les remboursements.

Les commissions non payées (En attente ou Approuvée) sont simplement mises à jour. Une commission Approuvée dont le montant change repasse En attente pour être vérifiée à nouveau. Une commission qui n\'est plus due (vente supprimée, entièrement retournée, commercial modifié) est supprimée.

Les commissions payées ne sont jamais modifiées. La différence devient une nouvelle ligne En attente marquée Ajustement : positive lorsqu\'un montant supplémentaire est dû (par exemple, le reste d\'une vente Montant payé a été réglé), négative lorsque le commercial a été trop payé (par exemple après un retour). Approuvez-la et incluez-la dans le prochain reçu du commercial.

Chaque commission conserve les conditions de la règle (type, taux, seuil, plafond) au moment où elle a été acquise. Modifier ou désactiver une règle par la suite ne modifie pas le calcul des ventes plus anciennes lorsqu\'elles sont recalculées.',
'Comm_G_T_Permissions' => 'Qui peut faire quoi',
'Comm_G_Permission' => 'Permission',
'Comm_G_Lets_You' => 'Ce qu\'elle permet',
'Comm_G_P_View' => 'Voir toutes les pages Commissions : programmes, commerciaux, règles, reçus, le rapport et ce guide.',
'Comm_G_P_Add' => 'Créer des programmes, des commerciaux et des règles, et enregistrer des Reçus de commission (payer les commerciaux).',
'Comm_G_P_Edit' => 'Modifier les programmes, les commerciaux et les règles, et approuver ou annuler des commissions dans le Rapport de commissions.',
'Comm_G_P_Delete' => 'Supprimer des programmes, des commerciaux et des règles.',
'Comm_G_T_Faq' => 'Questions et réponses',
'Comm_G_Q_Empty' => 'J\'ai tout configuré, mais le Rapport de commissions est vide.',
'Comm_G_A_Empty' => 'Vérifiez que : la vente a été enregistrée après la création de la règle ; la vente est Terminée ; la vente a un commercial (choisi sur la vente, ou l\'utilisateur qui l\'a réalisée est lié à un commercial) ; le programme est actif et la date de la vente est comprise dans ses dates ; la règle est active et s\'applique à ce commercial ; et la vente atteint ou dépasse le seuil minimum de la règle. Vérifiez aussi le filtre de date du rapport : il filtre selon la date à laquelle la commission a été calculée.',
'Comm_G_Q_Twice' => 'Un commercial a reçu deux commissions pour une même vente.',
'Comm_G_A_Twice' => 'Deux règles ont payé : soit le programme est réglé sur « Toutes les règles correspondantes paient », soit les règles se trouvent dans deux programmes actifs différents (chaque programme paie de son côté). Réglez le programme sur « Seule la règle la plus prioritaire paie » si une seule doit payer. Réenregistrer une vente ne duplique jamais une commission.',
'Comm_G_Q_Rate' => 'Si je modifie le taux d\'une règle, les anciennes commissions changent-elles ?',
'Comm_G_A_Rate' => 'Non. Chaque commission conserve les conditions de la règle sous laquelle elle a été acquise, même si sa vente est recalculée plus tard. Le nouveau taux s\'applique aux commissions acquises à partir de maintenant.',
'Comm_G_Q_Return' => 'Le client a retourné la marchandise. Qu\'advient-il de la commission ?',
'Comm_G_A_Return' => 'Elle est réduite automatiquement. Un retour reçu diminue le total de la vente et un remboursement diminue le montant payé. Si la commission n\'a pas encore été payée, elle est mise à jour (ou supprimée en cas de retour total). Si elle a déjà été payée, un Ajustement négatif est ajouté et déduit du prochain reçu du commercial.',
'Comm_G_Q_Wrong_Agent' => 'J\'ai crédité le mauvais commercial. Comment corriger ?',
'Comm_G_A_Wrong_Agent' => 'Modifiez la vente, choisissez le bon Commercial et enregistrez. Les commissions sont transférées au bon commercial. Si le premier commercial avait déjà été payé, un Ajustement négatif est ajouté pour lui.',
'Comm_G_Q_Inactive' => 'Que se passe-t-il lorsque je désactive un commercial ?',
'Comm_G_A_Inactive' => 'Il ne perçoit plus rien sur les nouvelles ventes et est masqué dans les sélecteurs de commerciaux. Ses commissions existantes sont conservées, peuvent encore être approuvées et payées, et suivent toujours les modifications de ses ventes. Une vente enregistrée avec ce commercial ne sera pas réattribuée à un autre commercial.',
'Comm_G_Q_Partial' => 'Comment les règles Montant payé gèrent-elles les paiements partiels ?',
'Comm_G_A_Partial' => 'Une vente impayée ne rapporte rien. La commission est créée dès la première somme reçue (au moment de la vente ou lors de l\'ajout d\'un paiement) et augmente au fur et à mesure des paiements suivants. Si une partie a déjà été payée, le reste arrive sous forme d\'Ajustement positif.',
'Comm_G_Q_Undo' => 'Puis-je annuler un paiement ou une annulation ?',
'Comm_G_A_Undo' => 'Un paiement, non : l\'état Payée est définitif et les reçus ne peuvent être ni modifiés ni supprimés ; vérifiez donc les commissions cochées et le montant avant d\'enregistrer. Une annulation, oui : cochez la ligne dans le Rapport de commissions et cliquez sur Recalculer, ou réenregistrez la vente dans Modifier la vente.',
'Comm_G_Q_Dates' => 'Quelle date est utilisée pour les dates du programme ?',
'Comm_G_A_Dates' => 'La date propre de la vente, et non le jour de son enregistrement. Une vente datée du mois dernier n\'utilise que les programmes valides le mois dernier.',
'Comm_G_When_Changes' => 'Ensuite, toute modification d\'une vente qui a déjà des commissions les met à jour automatiquement : paiements modifiés ou supprimés, retours et remboursements, passage de la vente hors du statut Terminée, ou suppression de la vente.',
'Comm_G_F_Program_Mode' => 'Ce qui se passe lorsque plusieurs règles de ce programme correspondent à la même vente. « Seule la règle la plus prioritaire paie » : les règles sont essayées de la Priorité la plus élevée à la plus basse, et la première éligible paie. « Toutes les règles correspondantes paient » : toutes paient et les montants s\'additionnent.',
'Comm_G_Q_Mode_Old' => 'J\'ai défini des priorités, mais les règles s\'additionnent toujours.',
'Comm_G_A_Mode_Old' => 'Ce programme est réglé sur « Toutes les règles correspondantes paient ». Les programmes créés avant l\'existence de ce paramètre conservent ce comportement afin que leurs versements ne changent pas. Modifiez le programme et choisissez « Seule la règle la plus prioritaire paie ».',
'Comm_G_Q_Negative' => 'Pourquoi y a-t-il une commission négative ?',
'Comm_G_A_Negative' => 'Il s\'agit d\'un Ajustement : le commercial a été payé davantage que ce que la vente rapporte désormais, en raison d\'un retour, d\'un remboursement, d\'un total inférieur, d\'un changement de commercial ou d\'une vente supprimée. Approuvez-le et cochez-le dans le prochain reçu du commercial pour qu\'il soit déduit.',
'Comm_Rule_Mode' => 'Lorsque plusieurs règles correspondent',
'Comm_Mode_Highest' => 'Seule la règle la plus prioritaire paie',
'Comm_Mode_All' => 'Toutes les règles correspondantes paient (elles s\'additionnent)',
'Comm_Mode_Highest_Short' => 'La plus prioritaire l\'emporte',
'Comm_Mode_All_Short' => 'Les règles s\'additionnent',
'Comm_Mode_Highest_Help' => 'Les règles sont essayées de la Priorité la plus élevée à la plus basse ; la première éligible pour la vente paie et les autres sont ignorées. Idéal pour les paliers, par exemple 7 % au-dessus de 10,000 en priorité 10 et 5 % pour tout le reste en priorité 0.',
'Comm_Mode_All_Help' => 'Chaque règle qui correspond au commercial paie sur la vente, les montants s\'additionnent donc. La Priorité ne définit que l\'ordre.',
'Comm_Priority_Help_Highest' => 'Ce programme ne paie que la règle éligible la plus prioritaire. Donnez à cette règle une Priorité supérieure à celle des règles qu\'elle doit devancer. En cas d\'égalité, une règle Commercial spécifique l\'emporte sur une règle Tous les commerciaux.',
'Comm_Priority_Help_All' => 'Ce programme paie chaque règle correspondante : cette règle s\'ajoute donc aux autres. La Priorité ne définit que l\'ordre.',
'Comm_Recalculate' => 'Recalculer',
'Comm_Recalculate_Help' => 'Recalcule les ventes des lignes cochées à partir de leurs chiffres actuels, y compris les commissions qui avaient été annulées.',
'Comm_Adjustment' => 'Ajustement',
'Comm_Adjustment_Help' => 'Une correction d\'une commission déjà payée, car la vente a été modifiée par la suite. Un montant négatif est déduit du prochain reçu du commercial.',
'Comm_Cancel_Confirm' => 'Annuler les commissions sélectionnées ?',
'Comm_Cancel_Confirm_Help' => 'Elles ne seront pas payées et resteront annulées même si des paiements ou des retours arrivent plus tard. Enregistrer la vente dans Modifier la vente ou cliquer sur Recalculer les recalcule.',
'Fashion_Tiles_Hint' => 'Ajoutez vos propres vignettes (image, titre et lien) pour remplacer les vignettes de catégories automatiques.',

// Online Store: Car Dealership theme
'Car_Dealership_Theme' => 'Thème Concession automobile',
'Cars_Theme_Hint' => 'Les voitures sont des produits ordinaires : ajoutez le prix, les photos et la description comme d\'habitude, puis remplissez la carte Détails du véhicule dans le formulaire produit (marque, modèle, année, kilométrage …). Les clients envoient des demandes de renseignements, des demandes d\'essai et des demandes d\'estimation de reprise, qui arrivent dans Boutique › Prospects véhicules.',
'CdSection_search' => 'Panneau de recherche',
