'CdSection_makes' => 'Acheter par marque',
'CdSection_finance' => 'Simulateur de financement',
'CdSection_trade_in' => 'Formulaire d\'estimation de reprise',
'CdSection_trust' => 'Bandeau de confiance',
'CdSection_visit' => 'Visiter le showroom',
'Cars_Featured_Count' => 'Voitures à la une',
'Cars_Latest_Count' => 'Dernières voitures',
'Cars_Makes_Count' => 'Marques affichées',
'Cars_Texts' => 'Textes de la page d\'accueil',
'Cars_Hero_Title' => 'Titre de la bannière',
'Cars_Hero_Title_Hint' => 'Utilisé lorsqu\'aucune diapositive de bannière n\'est ajoutée, et pour les diapositives sans titre.',
'Cars_Hero_Subtitle' => 'Sous-titre de la bannière',
'Cars_Featured_Title' => 'Titre de la section à la une',
'Cars_Latest_Title' => 'Titre des derniers arrivages',
'Cars_Finance_Title' => 'Titre de la section financement',
