'Rst_Guide_Step_Staff' => 'Autorisations du personnel',
'Rst_Guide_Step_Staff_Help' => 'Rôles pouvant prendre les commandes : {waiters} ; utiliser l\'écran de cuisine : {kitchen} ; encaisser : {cashiers}. Ne donnez à chaque rôle que ce dont ce poste a besoin (voir « Qui fait quoi »).',
'Rst_Guide_Step_First' => 'Votre première addition',
'Rst_Guide_Step_First_Ok' => '{n} additions encaissées jusqu\'à présent.',
'Rst_Guide_Step_First_Help' => 'Installez une table de test sur le plan de salle, ajoutez un plat, envoyez-le, marquez-le prêt sur l\'écran de cuisine et encaissez le paiement.',
'Rst_Guide_Step_Qr' => 'Commande à table par QR',
'Rst_Guide_Step_Qr_On' => 'Activée. {n} tables ont un code QR.',
'Rst_Guide_Step_Qr_Help' => 'Les clients scannent un code sur la table, choisissent leurs plats sur leur téléphone et les envoient à la commande de la table. Activez-la dans Paramètres du restaurant, puis imprimez les codes.',
'Rst_Guide_Step_Booking' => 'Réservation de table en ligne',
'Rst_Guide_Step_Booking_On' => 'Activée. Les réservations de la boutique en ligne arrivent dans Réservations pour être confirmées.',
'Rst_Guide_Step_Booking_Help' => 'Permettez aux clients de réserver une table depuis la boutique en ligne. Définissez les horaires de réservation, l\'intervalle et le groupe le plus grand dans Paramètres du restaurant.',
'Rst_Guide_Step_Store' => 'Boutique en ligne et thème Restaurant',
'Rst_Guide_Step_Store_On' => 'Le thème Restaurant est actif. Les commandes en ligne parviennent à la cuisine : {mode}.',
'Rst_Guide_Step_Store_Help' => 'Dans Boutique en ligne › Paramètres, choisissez le thème « Restaurant » : la page d\'accueil devient votre menu, avec suppléments, retrait / livraison et réservation de table.',
'Rst_Guide_How' => 'Fonctionnement',
'Rst_Guide_Service' => 'Un service, étape par étape',
'Rst_Guide_Service_1_T' => 'Installer',
'Rst_Guide_Service_1' => 'Sur le plan de salle, choisissez une table libre, saisissez le nombre de clients et le serveur, puis « Installer les clients et prendre la commande ». Un groupe ayant réservé est installé depuis sa réservation.',
'Rst_Guide_Service_2_T' => 'Commander',
'Rst_Guide_Service_2' => 'Touchez les plats sur l\'écran de commande. Choisissez les suppléments, la place et la suite ; ajoutez une note pour la cuisine. Mettez une suite en attente pour la lancer plus tard.',
'Rst_Guide_Service_3_T' => 'Envoyer',
'Rst_Guide_Service_3' => '« Envoyer » place les nouveaux plats sur un même ticket de cuisine. Les plats pas encore envoyés peuvent encore être modifiés ou retirés ; ensuite, ils ne peuvent plus qu\'être annulés avec un motif.',
'Rst_Guide_Service_4_T' => 'Cuisiner',
'Rst_Guide_Service_4' => 'L\'écran de cuisine affiche le ticket à chaque poste. Les cuisiniers le commencent, cochent les plats au fur et à mesure et le valident lorsque tout est prêt.',
'Rst_Guide_Service_5_T' => 'Servir',
'Rst_Guide_Service_5' => 'Les plats prêts s\'affichent sur le plan de salle et l\'écran de commande. Le serveur les apporte et touche « Marquer comme servi ».',
'Rst_Guide_Service_6_T' => 'Encaisser',
'Rst_Guide_Service_6' => '« Addition et paiement » imprime l\'addition et encaisse le paiement : addition complète, partagée à parts égales ou par article. Chaque paiement est une vente POS normale.',
'Rst_Guide_Service_7_T' => 'Débarrasser',
'Rst_Guide_Service_7' => 'Lorsque tout est payé, la commande se clôture et la table passe à « À nettoyer » (ou directement à libre, selon les Paramètres du restaurant).',
'Rst_Guide_Roles' => 'Qui fait quoi',
'Rst_Guide_Roles_Help' => 'Les autorisations du restaurant sont attribuées par rôle dans Autorisations de groupe. Un utilisateur peut cumuler les autorisations de plusieurs rôles.',
'Rst_Guide_Job' => 'Poste',
'Rst_Guide_Give' => 'Attribuer ces autorisations',
'Rst_Guide_Job_Waiter' => 'Serveur',
'Rst_Guide_Job_Cook' => 'Cuisinier',
'Rst_Guide_Job_Cashier' => 'Caissier',
'Rst_Guide_Job_Host' => 'Hôte / accueil',
'Rst_Guide_Job_Supervisor' => 'Superviseur',
'Rst_Guide_Job_Manager' => 'Responsable',
'Rst_Guide_Menu' => 'Menu, postes et suppléments',
'Rst_Guide_Menu_1' => 'Chaque produit que vous vendez peut être un plat. Restaurant › Menu (ou la carte « Détails du plat » du formulaire produit) ajoute les informations du restaurant.',
'Rst_Guide_Menu_2' => 'Les groupes de suppléments contiennent des choix avec un prix : « Taille » (choisir 1) ou « Extras » (jusqu\'à 3). Les règles sont vérifiées à chaque commande, y compris en ligne.',
'Rst_Guide_Menu_3' => 'Un supplément peut consommer un ingrédient : liez « Supplément fromage » à votre produit Fromage et chaque supplément déduit ce stock.',
'Rst_Guide_Menu_4' => 'Marquez un plat épuisé pour aujourd\'hui d\'un simple interrupteur ; il revient automatiquement le lendemain. Les horaires des repas (petit-déjeuner, déjeuner, dîner) limitent les moments où un plat est proposé.',
'Rst_Guide_Menu_5' => 'Une recette est un produit combiné : avec le stock virtuel des produits combinés activé, la vente du plat déduit ses composants du stock.',
'Rst_Guide_Kitchen' => 'Écran de cuisine',
'Rst_Guide_Kitchen_1' => 'Ouvrez Restaurant › Cuisine sur un écran en cuisine. Choisissez le poste ; les plats sans poste s\'affichent sur tous les postes.',
'Rst_Guide_Kitchen_2' => 'Les tickets passent à l\'orange puis au rouge à mesure qu\'ils attendent (Paramètres du restaurant › en retard après N minutes). Un bip annonce les nouveaux tickets.',
'Rst_Guide_Kitchen_3' => 'Commencer → cocher les plats → Valider. « Terminé à ce poste » ne termine que les plats de ce poste sur un ticket partagé.',
'Rst_Guide_Kitchen_4' => 'Les tickets servis restent affichés 15 minutes afin qu\'une erreur puisse être rappelée. Les tickets peuvent être imprimés sur une imprimante 80 mm.',
'Rst_Guide_Kitchen_5' => 'Les commandes de la boutique en ligne et des codes QR des tables sont marquées « En ligne » ou « QR » sur leur ticket.',
'Rst_Guide_Bills' => 'Additions et paiements',
'Rst_Guide_Bills_1' => 'Chaque paiement est une vente POS normale : le stock, la caisse, la comptabilité, les points de fidélité et la facturation électronique fonctionnent comme au POS.',
'Rst_Guide_Bills_2' => 'Les frais de service sont un pourcentage des plats hors taxes, pour la consommation sur place (ou pour chaque commande, selon votre réglage). Les pourboires sont un pourcentage prédéfini ou un montant.',
'Rst_Guide_Bills_3' => 'Une remise nécessite l\'autorisation « Remises restaurant » et est plafonnée par la remise maximale définie dans Paramètres du restaurant.',
'Rst_Guide_Bills_4' => 'L\'arrondi se fait vers le bas selon votre pas, en faveur du client, sur le paiement qui solde l\'addition.',
'Rst_Guide_Bills_5' => 'Partage à parts égales : une seule vente, une ligne de paiement par personne (parts au centime près). Partage par article : les plats de chaque client deviennent sa propre vente ; choisissez une place pour sélectionner ses plats.',
'Rst_Guide_Bills_6' => 'Si l\'addition a changé après avoir été présentée (un plat ajouté depuis un code QR, un pourboire modifié), le paiement est refusé afin que le client ne soit jamais facturé pour quelque chose qu\'il n\'a pas vu.',
'Rst_Guide_Bills_7' => 'Les plats payés ne peuvent pas être annulés. Si le reste impayé d\'une commande est annulé, la commande se clôture comme payée et la table peut être débarrassée.',
'Rst_Guide_Bookings' => 'Réservations et liste d\'attente',
'Rst_Guide_Bookings_1' => 'Les réservations retiennent une table pendant leur durée (valeur par défaut dans Paramètres du restaurant). Deux réservations ne peuvent jamais se chevaucher sur une même table.',
'Rst_Guide_Bookings_2' => 'Le plan de salle affiche la prochaine réservation de chaque table et avertit lorsqu\'elle approche ; « Ils sont arrivés — installer » installe le groupe.',
'Rst_Guide_Bookings_3' => 'Passé le délai de non-présentation, un groupe en retard peut être marqué comme non présenté ; en cas d\'erreur, la réservation peut être restaurée.',
'Rst_Guide_Bookings_4' => 'La liste d\'attente garde les clients sans réservation dans l\'ordre avec leur attente annoncée. Appelez-les ou écrivez-leur sur WhatsApp lorsqu\'une table est prête, puis installez-les.',
'Rst_Guide_Bookings_5' => 'Les réservations en ligne arrivent avec le statut « Réservée » (un badge dans la barre latérale les compte) pour que vous les confirmiez.',
'Rst_Guide_Online' => 'Commandes en ligne, menus QR et réservation en ligne',
'Rst_Guide_Online_1' => 'Avec le thème de boutique Restaurant, la page d\'accueil de la boutique en ligne est votre menu, avec suppléments et filtres alimentaires ; les clients paient au moment du paiement comme d\'habitude.',
'Rst_Guide_Online_2' => '« Commandes en ligne vers la cuisine » détermine quand elles parviennent à l\'écran de cuisine : à la commande (payée, ou client connecté payant à la livraison / au retrait), à l\'acceptation, ou jamais.',
'Rst_Guide_Online_3' => 'Les codes QR des tables (Configuration de la salle › Codes QR des tables) ouvrent le menu de cette table. « Nouveau lien » désactive un code imprimé.',
'Rst_Guide_Online_4' => 'Les commandes QR attendent sur la commande de la table qu\'un serveur les envoie, sauf si « Envoyer directement les commandes QR en cuisine » est activé. Les clients paient auprès du personnel.',
'Rst_Guide_Online_5' => 'La réservation en ligne ne propose que des horaires où une table adaptée au groupe est libre pendant toute la réservation, et limite chaque numéro de téléphone à 3 réservations à venir.',
'Rst_Guide_Online_6' => 'Tout ceci fait partie de la boutique en ligne : elle doit être activée et incluse dans votre plan.',
'Rst_Guide_Reports' => 'Tableau de bord et rapports',
'Rst_Guide_Reports_1' => 'Le tableau de bord compare aujourd\'hui au même jour de la semaine dernière : ventes, additions, clients, addition moyenne, annulations et remises, ainsi que ce qui se passe en ce moment.',
'Rst_Guide_Reports_2' => 'Les ventes correspondent aux additions du restaurant plus les commandes en ligne parvenues en cuisine. Les ventes de plats et les marges sont hors taxes, calculées avec le coût de chaque produit.',
'Rst_Guide_Reports_3' => 'Rapports : ventes par jour et par mode de paiement, plats, annulations (avec motifs), personnel, temps en cuisine et réservations — chacun s\'exporte vers Excel.',
'Rst_Guide_Reports_4' => 'Le personnel limité à certaines agences ne voit que ses agences ; les commandes sans agence sont partagées par tous.',
'Rst_Guide_Faq' => 'Bon à savoir',
'Rst_Guide_Faq_1_Q' => 'Une commande à emporter a été payée avant que j\'appuie sur « Envoyer ». Sera-t-elle préparée ?',
'Rst_Guide_Faq_1_A' => 'Oui. Le paiement envoie en cuisine tous les plats qui n\'avaient pas encore été envoyés.',
'Rst_Guide_Faq_2_Q' => 'Pourquoi ne puis-je pas libérer une table ?',
'Rst_Guide_Faq_2_A' => 'Sa commande contient encore des plats impayés. Encaissez le paiement, annulez ce qui n\'a pas été consommé ou annulez la commande (uniquement si rien n\'a encore été payé).',
'Rst_Guide_Faq_3_Q' => 'Deux tables ont été rapprochées. Que deviennent leurs commandes ?',
'Rst_Guide_Faq_3_A' => '« Joindre les tables » déplace les plats (et les éventuels paiements) de la seconde table vers la commande de la table principale ; « Séparer » sépare à nouveau les tables.',
'Rst_Guide_Faq_4_Q' => 'Les paiements par carte peuvent-ils utiliser Stripe ici ?',
'Rst_Guide_Faq_4_A' => 'Non. Les paiements par carte Stripe nécessitent le formulaire de carte du POS ; pour un terminal de paiement, ajoutez un mode de paiement tel que « Carte » et utilisez-le sur l\'addition.',
'Rst_Guide_Faq_5_Q' => 'Un plat est en rupture de stock dans une seule agence.',
'Rst_Guide_Faq_5_A' => 'Le stock est déduit de l\'agence de la commande (celle de la zone de la table, sinon l\'agence par défaut des Paramètres du restaurant). Utilisez « Épuisé aujourd\'hui » pour arrêter rapidement les commandes.',
'Rst_Guide_Faq_6_Q' => 'Ai-je besoin d\'une imprimante ?',
'Rst_Guide_Faq_6_A' => 'Non. Les additions, reçus et tickets de cuisine s\'impriment depuis le navigateur sur n\'importe quelle imprimante ; les imprimantes de tickets 80 mm conviennent le mieux.',
'Rst_Guide_Faq_7_Q' => 'D\'où viennent les menus du restaurant dans la boutique en ligne ?',
'Rst_Guide_Faq_7_A' => 'Des mêmes produits, catégories et suppléments. Les produits masqués de la boutique en ligne et les catégories non affichées dans la boutique n\'apparaissent ni dans le menu en ligne ni dans le menu QR.',

// Rental — business types + website booking (Rental store theme).
'Rental_Website_Not_Ready' => 'Installez la dernière mise à jour pour utiliser les types d\'activité et la réservation sur le site web.',
'Rental_Business_Type' => 'Type d\'activité',
'Rental_Business_Type_Help' => 'Cochez ce que vous louez. Le formulaire d\'article, les catégories, les filtres et votre site web n\'affichent alors que ces types et leurs champs.',
'Rental_Business_Type_All' => 'Rien de coché : tous les types sont disponibles.',
'Rental_Website_Booking' => 'Réservation sur le site web',
'Rental_Website_Theme_Off' => 'Votre boutique en ligne utilise un autre thème. Choisissez le thème Location dans Paramètres de la boutique pour publier vos locations.',
'Rental_Open_Store_Settings' => 'Ouvrir les paramètres de la boutique',
'Rental_Website_Booking_Help' => 'Les visiteurs choisissent des dates sur votre site web et envoient une demande de réservation. Elle arrive dans Réservations en tant que blocage provisoire : confirmez-la, convertissez-la en contrat ou annulez-la.',
'Rental_Website_Hold' => 'Bloquer une demande pendant',
'Rental_Website_Hold_Help' => 'Les articles restent bloqués pendant ce délai le temps que vous répondiez. Une confirmation les garde jusqu\'à la fin de la location.',
