'Rental_Pickup_Locations' => 'Lieux de prise en charge',
'Rental_Pickup_Locations_Help' => 'Véhicules : les lieux que les clients peuvent choisir pour la prise en charge et la restitution. Laissez vide si tout est retiré à votre agence.',
