'Bkm_Guide_Website' => 'Une réservation depuis le site web',
'Bkm_Guide_Website_1_T' => 'Choisir un service',
'Bkm_Guide_Website_1' => 'le client commence depuis le formulaire de votre page d\'accueil ou depuis la page Réserver.',
'Bkm_Guide_Website_2_T' => 'Choisir un créneau ou envoyer une demande',
'Bkm_Guide_Website_2' => 'les créneaux libres découlent des horaires, des jours de repos et des autres réservations de votre personnel ; une demande indique simplement un jour et un moment de la journée souhaités.',
'Bkm_Guide_Website_3_T' => 'Ses coordonnées',
