'Bkm_Guide_Website_4_T' => 'Acompte',
'Bkm_Guide_Website_4' => 'si vous en demandez un, le client le paie immédiatement pour bloquer le créneau.',
'Bkm_Guide_Website_5_T' => 'En attente de votre réponse',
