'Bkm_Guide_Website_6_T' => 'Sa page de réservation',
'Bkm_Guide_Website_6' => 'le client la suit via le lien de son e-mail : statut, ajout au calendrier, annulation, réponse à un créneau proposé.',
'Bkm_Guide_Requests' => 'Répondre aux demandes',
'Bkm_Guide_Requests_1' => 'Demandes affiche toutes les réservations qui attendent votre réponse, la plus ancienne en premier, avec un badge dans le menu.',
'Bkm_Guide_Requests_2' => '« Confirmer » choisit un membre du personnel pour vous si vous laissez le champ vide, et vérifie que le créneau est toujours libre.',
'Bkm_Guide_Requests_3' => 'Proposez un autre créneau si celui du client ne convient pas — il l\'accepte depuis sa page de réservation.',
'Bkm_Guide_Requests_4' => 'Refusez en indiquant un motif ; le client le voit.',
'Bkm_Guide_Requests_5' => 'Un blocage expiré libère le créneau ; la réservation reste en place jusqu\'à votre réponse.',
'Bkm_Guide_Day' => 'Le jour J',
'Bkm_Guide_Day_1' => 'La vue du jour affiche côte à côte les réservations de chaque membre du personnel.',
'Bkm_Guide_Day_2' => 'Utilisez « Marquer arrivé » lorsque le client se présente.',
'Bkm_Guide_Day_3' => '« Terminer et encaisser » crée la vente via le POS, avec l\'acompte déjà déduit.',
'Bkm_Guide_Day_4' => '« Terminer sans encaisser » si le paiement a été effectué autrement.',
'Bkm_Guide_Day_5' => '« Marquer absent » une fois l\'heure de début passée.',
'Bkm_Guide_Day_6' => 'Le tableau de bord affiche le programme du jour, ce qui reste à venir et ce qui n\'est pas encore encaissé.',
'Bkm_Guide_Deposits' => 'Acomptes',
'Bkm_Guide_Deposits_1' => 'Définissez le montant dans Paramètres de réservation › Acompte ; un service peut avoir le sien.',
'Bkm_Guide_Deposits_2' => 'Les clients paient via les prestataires de paiement configurés dans Boutique en ligne › Passerelle de paiement, dans votre devise de base.',
'Bkm_Guide_Deposits_3' => 'Le créneau est bloqué le temps du paiement ; les réservations impayées peuvent être annulées automatiquement.',
'Bkm_Guide_Deposits_4' => 'Un paiement abouti sans que le client soit revenu sur le site est récupéré automatiquement.',
'Bkm_Guide_Deposits_5' => 'Lorsque vous encaissez la réservation, l\'acompte constitue le premier paiement de la vente.',
'Bkm_Guide_Deposits_6' => 'Les remboursements se font chez votre prestataire de paiement ; marquez ensuite l\'acompte comme remboursé sur la réservation.',
'Bkm_Guide_Messages' => 'E-mails, WhatsApp et rappels',
'Bkm_Guide_Messages_1' => 'Les clients reçoivent un e-mail lorsque leur réservation est reçue, confirmée, refusée, modifiée ou annulée.',
'Bkm_Guide_Messages_2' => 'Vous en recevez un pour chaque nouvelle réservation du site web, chaque annulation par un client et chaque acompte payé.',
'Bkm_Guide_Messages_3' => 'Un rappel est envoyé avant chaque visite confirmée (Paramètres de réservation › Notifications).',
'Bkm_Guide_Messages_4' => 'Activez « Envoyer aussi par WhatsApp » pour y envoyer les mêmes messages.',
'Bkm_Guide_Messages_5' => 'Chaque message est listé sur la réservation, avec la raison de son non-envoi le cas échéant.',
'Bkm_Guide_Customers' => 'Clients, CRM et portail',
'Bkm_Guide_Customers_1' => 'Une réservation du site web est ajoutée à vos clients ; une personne qui réserve à nouveau avec le même e-mail et le même téléphone est reconnue.',
'Bkm_Guide_Customers_2' => 'Si votre plan inclut le CRM, les réservations peuvent être notées sur le client ou son prospect, et les demandes peuvent ouvrir une opportunité.',
'Bkm_Guide_Customers_3' => 'Les clients disposant d\'un compte sur le portail client y voient leurs réservations et peuvent annuler ou répondre à un créneau proposé.',
'Bkm_Guide_Customers_4' => 'Les clients connectés à la boutique retrouvent leurs réservations dans Mon compte.',
'Bkm_Guide_Roles' => 'Qui peut faire quoi',
'Bkm_Guide_Roles_Help' => 'Donnez à chaque rôle uniquement les autorisations dont il a besoin (Paramètres › Autorisations de groupe).',
'Bkm_Guide_Job' => 'Poste',
'Bkm_Guide_Give' => 'À attribuer',
'Bkm_Guide_Job_Front_Desk' => 'Accueil',
'Bkm_Guide_Job_Staff_Member' => 'Membre du personnel',
'Bkm_Guide_Job_Manager' => 'Responsable',
'Bkm_Guide_Job_Owner' => 'Propriétaire ou comptable',
'Bkm_Guide_Faq' => 'Questions',
'Bkm_Guide_Faq_1_Q' => 'Pourquoi un service n\'apparaît-il pas sur le site web ?',
'Bkm_Guide_Faq_1_A' => 'Il lui faut des détails de réservation (Services), « Afficher sur le site web » activé, le produit actif et — pour choisir un créneau — une personne réservable en ligne qui l\'assure.',
'Bkm_Guide_Faq_2_Q' => 'Pourquoi n\'y a-t-il aucun créneau libre ?',
'Bkm_Guide_Faq_2_A' => 'Vérifiez les horaires de travail du personnel, les jours de repos, les jours fériés et les congés approuvés, le délai de prévenance et le nombre de jours à l\'avance auxquels les clients peuvent réserver.',
'Bkm_Guide_Faq_3_Q' => 'Deux clients peuvent-ils prendre le même créneau ?',
'Bkm_Guide_Faq_3_A' => 'Non. Le créneau est revérifié au moment de la réservation, et une réservation bloquée ou confirmée l\'occupe. Les cours partagent leurs places jusqu\'à leur limite.',
'Bkm_Guide_Faq_4_Q' => 'Que se passe-t-il lorsqu\'un blocage expire ?',
'Bkm_Guide_Faq_4_A' => 'Le créneau redevient libre pour les autres. La réservation reste dans Demandes jusqu\'à votre réponse (ou est annulée si son acompte n\'a pas été payé).',
'Bkm_Guide_Faq_5_Q' => 'Les clients ont-ils besoin d\'un compte ?',
'Bkm_Guide_Faq_5_A' => 'Non. Ils reçoivent un lien privé vers leur page de réservation. Les comptes boutique et portail listent aussi leurs réservations.',
'Bkm_Guide_Faq_6_Q' => 'Où va l\'argent ?',
'Bkm_Guide_Faq_6_A' => 'Les acomptes vont chez votre prestataire de paiement ; le reste est encaissé au POS lorsque vous encaissez la réservation. Les rapports comptent le chiffre d\'affaires de ces ventes.',
'Bkm_Guide_Faq_7_Q' => 'Pourquoi un client n\'a-t-il pas reçu d\'e-mail ?',
'Bkm_Guide_Faq_7_A' => 'Ouvrez la réservation : sa liste de messages indique si chaque e-mail a été envoyé, a échoué ou a été ignoré, et pourquoi.',
'Bkm_Staff_Removed' => 'retiré',
'Bkm_Staff_Not_Bookable' => 'N\'est plus réservable',
'Bkm_Requests_Cut' => 'Affichage des {n} plus anciennes. Répondez à certaines pour voir le reste, ou faites une recherche.',

