'Pf_Guide_1' => 'Dans Printful, ajoutez une boutique de type {store} et créez-y vos produits.',
'Pf_Guide_2' => 'Créez un jeton privé sur {portal} pour cette boutique avec les portées {scopes}. Collez-le dans l\'onglet Connexion et enregistrez ; si le jeton donne accès à plusieurs boutiques, choisissez-en une.',
