'Mkg_Guide_Ch_whatsapp_1' => 'Connectez une passerelle WhatsApp HTTP, ou l\'API Meta WhatsApp Cloud (graph.facebook.com).',
'Mkg_Guide_Ch_whatsapp_2' => 'Plus de 24 heures après le dernier message d\'un client, WhatsApp ne distribue que des modèles approuvés par Meta.',
'Mkg_Guide_Ch_whatsapp_3' => 'Avec l\'API Cloud, choisissez le modèle approuvé et renseignez ses paramètres dans la campagne.',
'Mkg_Guide_Ch_whatsapp_4' => 'Les clients sans numéro de téléphone sont ignorés.',
'Mkg_Guide_Variables' => 'Variables de personnalisation',
'Mkg_Guide_Variables_Help' => 'Saisissez-les dans l\'objet ou le message. Chacune est remplacée pour chaque destinataire, et laissée vide lorsque la valeur est inconnue.',
