'Mkg_Guide_Var_Unsubscribe' => 'Lien de désabonnement (prospects CRM uniquement ; ajouté automatiquement aux e-mails destinés aux prospects s\'il est absent)',
'Mkg_Guide_Schedule' => 'Planification',
'Mkg_Guide_Schedule_1' => 'Activez « Activer la planification » dans les Paramètres marketing, puis choisissez Planifier ainsi qu\'une date et une heure dans la campagne.',
'Mkg_Guide_Schedule_2' => 'Les campagnes arrivées à échéance sont vérifiées chaque minute et envoyées automatiquement.',
'Mkg_Guide_Schedule_3' => 'Une campagne en retard de plus d\'un jour est annulée plutôt qu\'envoyée tardivement. Modifiez-la et choisissez une nouvelle heure.',
'Mkg_Guide_Schedule_4' => 'Une campagne planifiée peut encore être modifiée, ou envoyée immédiatement avec Envoyer maintenant.',
