'Mkg_Guide_Roles' => 'Qui a besoin de quelle autorisation',
'Mkg_Guide_Roles_Help' => 'Dans Paramètres > Autorisations, n\'accordez à chaque rôle que ce dont il a besoin. N\'importe laquelle de ces autorisations donne accès à ce guide.',
'Mkg_Guide_Permission' => 'Autorisation',
'Mkg_Guide_Allows' => 'Permet de',
'Mkg_Guide_Perm_marketing_dashboard' => 'Voir le tableau de bord marketing : totaux et campagnes récentes.',
'Mkg_Guide_Perm_marketing_campaigns' => 'Créer, modifier, envoyer et supprimer des campagnes, et voir leurs destinataires.',
'Mkg_Guide_Perm_marketing_segments' => 'Créer et modifier des segments clients.',
'Mkg_Guide_Perm_marketing_templates' => 'Gérer les modèles SMS, WhatsApp et e-mail.',
'Mkg_Guide_Perm_marketing_reports' => 'Ouvrir les rapports marketing.',
'Mkg_Guide_Perm_marketing_settings' => 'Configurer les canaux (SMS, WhatsApp, expéditeur e-mail), la planification et la taille des lots.',
'Mkg_Guide_Faq' => 'Questions fréquentes',
'Mkg_Guide_Faq_1_Q' => 'Ma campagne reste en cours d\'envoi et rien ne part.',
'Mkg_Guide_Faq_1_A' => 'Le processus d\'envoi en arrière-plan ne l\'a pas prise en charge. Après 30 minutes sans progression, le bouton Envoyer maintenant réapparaît : cliquez dessus pour la reprendre. Si le problème se répète, demandez à l\'administrateur de la plateforme de vérifier que les tâches en arrière-plan (le queue worker) s\'exécutent.',
'Mkg_Guide_Faq_2_Q' => 'Les destinataires affichent « Skipped: Email channel disabled ».',
'Mkg_Guide_Faq_2_A' => 'Activez « Activer l\'e-mail » dans les Paramètres marketing, puis renvoyez la campagne.',
'Mkg_Guide_Faq_3_Q' => 'Les destinataires affichent « No mail server configured ».',
'Mkg_Guide_Faq_3_A' => 'Les campagnes e-mail passent uniquement par votre propre serveur de messagerie. Ajoutez-le dans Paramètres > Paramètres de messagerie.',
'Mkg_Guide_Faq_4_Q' => 'Moins de personnes ont reçu le message qu\'il n\'y en a dans mon segment.',
'Mkg_Guide_Faq_4_A' => 'Les clients sans adresse e-mail (E-mail) ou sans numéro de téléphone (SMS, WhatsApp) sont ignorés. Ouvrez la campagne pour voir qui a été ignoré et pourquoi.',
'Mkg_Guide_Faq_5_Q' => '« Envoyé » signifie-t-il que le client l\'a reçu ?',
'Mkg_Guide_Faq_5_A' => '« Envoyé » signifie que votre serveur de messagerie ou votre passerelle a accepté le message. La remise en boîte de réception, les ouvertures et le filtrage anti-spam ne sont pas suivis.',
'Mkg_Guide_Faq_6_Q' => 'Puis-je modifier une campagne après l\'avoir envoyée ?',
'Mkg_Guide_Faq_6_A' => 'Non. Les campagnes en cours d\'envoi et envoyées sont verrouillées ; créez plutôt une nouvelle campagne.',
'Mkg_Guide_Faq_7_Q' => 'Mes messages WhatsApp n\'arrivent pas.',
'Mkg_Guide_Faq_7_A' => 'Plus de 24 heures après le dernier message d\'un client, WhatsApp ne distribue que des modèles approuvés par Meta. Utilisez l\'API WhatsApp Cloud et choisissez un modèle approuvé dans la campagne.',
'Mkg_Guide_Faq_8_Q' => 'Si je renvoie une campagne, les clients la recevront-ils deux fois ?',
'Mkg_Guide_Faq_8_A' => 'La reprise d\'une campagne bloquée n\'envoie qu\'aux destinataires encore en attente : personne de déjà contacté ne reçoit de nouveau message. Renvoyer une campagne en échec repart de zéro avec une nouvelle liste.',

