'Pd_Line_Locked' => 'Cette ligne a été débitée sur le terminal. Annulez d\'abord le débit pour la modifier.',
'Pd_Needs_Online' => 'Les paiements par terminal de carte nécessitent une connexion Internet.',
'Pd_Device_Error' => 'Le terminal est injoignable.',
'Pd_Void_Charge' => 'Annuler le débit',
'Pd_Void_Charge_Confirm' => 'Annuler le paiement par carte de {amount} sur le terminal ?',
'Pd_Void_Before_Close' => 'Un paiement par carte a déjà été effectué sur le terminal. L\'annuler et fermer ?',
'Pd_Installments' => 'Versements',
'Pd_Single_Payment' => 'Paiement unique',
'Pd_Guide_How_Title' => 'Fonctionnement',
'Pd_Guide_How_Intro' => 'Un terminal POS est un terminal de paiement par carte ou une caisse enregistreuse fiscale placé à côté de la caisse. Stocky lui envoie le montant, attend que le client paie et n\'enregistre le paiement qu\'après l\'approbation du terminal.',
'Pd_Guide_Step_1' => 'Ajoutez le terminal ici : modèle, entrepôt et mode de paiement sous lequel ses paiements par carte sont enregistrés (par exemple « Carte de crédit »).',
'Pd_Guide_Step_2' => 'Choisissez comment Stocky y accède : un pont local sur l\'ordinateur de caisse, ou l\'API cloud de votre prestataire. Saisissez les identifiants et les clés fournis par votre banque ou votre prestataire.',
'Pd_Guide_Step_3' => 'Cliquez sur Tester la connexion. Les terminaux en pont local doivent être testés depuis l\'ordinateur de caisse sur lequel le pont s\'exécute.',
'Pd_Guide_Step_4' => 'Au POS, choisissez ce mode de paiement, cliquez sur « Débiter sur le terminal » et laissez le client payer. La vente peut être finalisée une fois le paiement approuvé par le terminal.',
'Pd_Guide_Step_5' => 'Consultez les Transactions pour repérer les paiements par carte effectués sans vente (par exemple un encaissement abandonné) et annulez-les ou remboursez-les.',
'Pd_Guide_Bridge_Text' => 'Pour les terminaux pilotés par le SDK d\'un fabricant sur le PC de caisse (appairage USB, série ou LAN). Le navigateur ne peut pas utiliser le SDK directement : un petit programme pont l\'encapsule donc et écoute sur cet ordinateur.',
'Pd_Guide_Bridge_Point_1' => 'Le POS envoie chaque requête à l\'URL du pont depuis le navigateur du caissier ; le serveur de Stocky n\'a jamais besoin d\'accéder au réseau de votre magasin.',
'Pd_Guide_Bridge_Point_2' => 'Les requêtes et les réponses sont signées avec le secret partagé, de sorte qu\'une approbation ne peut pas être falsifiée depuis le navigateur.',
'Pd_Guide_Bridge_Point_3' => 'Installez et lancez le pont sur chaque ordinateur qui encaisse des paiements par carte sur ce terminal.',
'Pd_Guide_Cloud_Text' => 'Pour les prestataires qui accèdent au terminal par Internet. Le serveur de Stocky appelle l\'API : rien n\'a donc besoin d\'être installé sur l\'ordinateur de caisse.',
'Pd_Guide_Cloud_Point_1' => 'L\'URL de l\'API doit être en https:// sur une adresse publique.',
'Pd_Guide_Cloud_Point_2' => 'Pendant que le client paie, Stocky demande le statut toutes les 2 secondes : l\'endpoint de statut doit donc reconnaître le paiement par sa référence ; si l\'API répond avant la fin de l\'opération carte (« pending »), c\'est l\'interrogation périodique qui tranche.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'L\'IDE280 est une caisse enregistreuse fiscale de nouvelle génération (YN ÖKC) équipée d\'un lecteur de carte. Elle s\'intègre normalement via le SDK ECR / GMP3 d\'Ingenico, ou via le service d\'intégration de votre banque.',
'Pd_Guide_Ide280_Point_1' => 'Appairez le terminal avec l\'ordinateur de caisse comme indiqué dans la documentation Ingenico / de votre banque, puis faites pointer le pont (ou les paramètres d\'API) vers celui-ci.',
'Pd_Guide_Ide280_Point_2' => 'Les montants sont envoyés à la fois en décimales et en kuruş (amount_minor), avec la devise TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Avec « Reçu fiscal complet », chaque article porte le département du terminal correspondant à son taux de TVA — faites correspondre les départements TVA à la programmation du terminal.',
'Pd_Guide_Protocol_Title' => 'Contrat pont / API',
'Pd_Guide_Protocol_Intro' => 'Stocky communique en JSON avec le pont ou l\'API. Les chemins ci-dessous sont les valeurs par défaut et peuvent être modifiés pour chaque terminal dans Avancé.',
'Pd_Guide_Operation' => 'Opération',
'Pd_Guide_Default_Endpoint' => 'Endpoint par défaut',
'Pd_Guide_When' => 'Quand',
'Pd_Guide_When_Ping' => 'Bouton Tester la connexion.',
'Pd_Guide_When_Sale' => 'Le caissier clique sur « Débiter sur le terminal ». Peut répondre une fois l\'opération carte terminée, ou immédiatement avec le statut « pending ».',
'Pd_Guide_When_Status' => 'Toutes les 2 secondes tant que le paiement est en attente.',
'Pd_Guide_When_Cancel' => 'Le caissier abandonne pendant l\'attente de la carte.',
'Pd_Guide_When_Void' => 'Annulation d\'un paiement (le jour même, montant total).',
'Pd_Guide_When_Refund' => 'Remboursement partiel ou total d\'un paiement.',
'Pd_Guide_Request_Title' => 'Requête',
'Pd_Guide_Request_Text' => 'Le corps envoyé par Stocky pour une vente. Le remboursement et l\'annulation transmettent le paiement d\'origine dans « original ».',
'Pd_Guide_Response_Title' => 'Réponse',
'Pd_Guide_Response_Text' => 'Les noms de champs sont lus de manière souple (y compris sous « data ») ; « status » ou response_code « 00 » détermine le résultat. Les numéros de carte sont stockés masqués.',
'Pd_Guide_Signing_Title' => 'Signature (pont)',
'Pd_Guide_Signing_Text' => 'Le pont doit vérifier la signature de Stocky, et doit signer le corps exact de sa réponse et renvoyer « reference » et « operation » — les réponses non signées, ou portant sur une autre opération, sont refusées.',
'Pd_Guide_Browser_Title' => 'Accès navigateur (pont)',
'Pd_Guide_Browser_Text' => 'La page POS appelle le pont depuis le navigateur : le pont doit donc renvoyer ces en-têtes CORS (y compris pour la requête de pré-vérification OPTIONS).',
'Pd_Guide_Safety_Title' => 'Bon à savoir',
'Pd_Guide_Safety_1' => 'Une vente n\'est enregistrée qu\'avec un paiement terminal approuvé du même montant ; un même paiement terminal ne peut jamais régler deux ventes.',
'Pd_Guide_Safety_2' => 'Fermer la fenêtre de paiement après le débit d\'une carte annule d\'abord ce débit.',
'Pd_Guide_Safety_3' => 'Si le terminal ne répond pas à temps, le paiement apparaît comme « Pas de réponse » : vérifiez le terminal, et annulez le débit depuis Transactions si la carte a été débitée.',
'Pd_Guide_Safety_4' => 'Les remboursements et annulations effectués ici ne concernent que l\'argent sur la carte ; ils ne modifient pas la vente. Enregistrez les marchandises rendues dans Retours de ventes.',
'Perm_Pos_Terminals_Manage' => 'Terminaux POS : gérer, rembourser et annuler',
'Perm_Pos_Terminals_Transactions' => 'Terminaux POS : voir les transactions',
'Pd_Check_Again' => 'Vérifier à nouveau',
'Pd_Lost_Track' => 'Contact perdu avant la réponse du terminal. Vérifiez le terminal, puis cliquez sur « Vérifier à nouveau » — ne débitez pas à nouveau tant que vous n\'êtes pas sûr.',
'Pd_Close_Anyway' => 'Le paiement par carte n\'a pas pu être annulé. Fermer quand même ? Il reste dans Terminaux POS › Transactions avec le statut « Débité sans vente » afin de pouvoir y être annulé ou remboursé.',
'Pd_Devices_Loading' => 'Chargement des terminaux de carte — réessayez dans un instant.',
