'Ord_Guide_PayAuto_Tip' => 'Se met à jour automatiquement lorsque des paiements sont enregistrés sur la vente. Cliquez pour voir comment enregistrer un paiement.',
'Ord_Guide_PayAuto_Intro' => 'Cette colonne indique la part de la commande déjà payée. Elle part du choix fait par le client lors du paiement, puis se met à jour automatiquement à mesure que des paiements sont enregistrés sur la vente créée lors de la confirmation de la commande. Elle ne peut pas être modifiée depuis cette page.',
'Ord_Guide_PayAuto_Paid' => 'Le montant total a été reçu. Si le client a payé en ligne via une passerelle de paiement, confirmer la commande crée la vente en statut « payée » et enregistre le paiement à votre place. Sinon, le statut passe à « payée » dès que les paiements enregistrés sur la vente couvrent le total.',
'Ord_Guide_PayAuto_Partial' => 'Un paiement a été enregistré sur la vente, mais une partie du total reste due.',
'Ord_Guide_PayAuto_Pending' => 'Aucun paiement n\'a encore été reçu : paiement à la livraison, virement bancaire ou autre mode de paiement différé. Confirmer la commande crée la vente en statut « impayée » ; vous enregistrez donc vous-même l\'argent une fois encaissé. Voir les étapes ci-dessous.',
'Ord_Guide_PayAuto_Note' => 'Le statut de paiement affiché ici suit la vente : il passe automatiquement à « Partiellement payé » ou « Payé » lorsque vous enregistrez un paiement, et revient en arrière si vous en supprimez un. C\'est la vente qui constitue l\'écriture comptable et qui alimente vos rapports de paiements et de bénéfices. Utilisez « Afficher les paiements » sur la vente pour consulter ou modifier ce que vous avez saisi.',
