'Oc_Orders_Desc' => 'Importe les commandes de la boutique en tant que ventes (références du type {ref}). Pour les commandes déjà importées, seuls le statut et le paiement sont mis à jour : vous pouvez donc les récupérer à nouveau sans risque.',
'Oc_Orders_Since' => 'Commandes depuis le',
'Oc_Guide_1' => 'Dans l\'onglet Connexion, téléchargez le {company} Connector.',
'Oc_Guide_2' => 'Dans l\'administration OpenCart, envoyez le fichier via {installer} et cliquez sur Install, puis installez le module dans {modules}.',
'Oc_Guide_3' => 'Ouvrez le module {name}, puis copiez l\'URL de la boutique et la clé secrète.',
'Oc_Guide_4' => 'Collez-les dans l\'onglet Connexion, enregistrez, puis lancez {test}. Cela indique aussi à la boutique où envoyer les nouvelles commandes.',
'Oc_Guide_5' => 'Configurez les produits : récupérez-les si la boutique possède déjà un catalogue, envoyez-les si c\'est {company} qui l\'a. Faites-le avant de compter sur le stock automatique, car {company} devient la source des quantités en stock.',
'Oc_Guide_6' => 'Récupérez une fois les commandes récentes si vous souhaitez un historique. Ensuite, les commandes arrivent d\'elles-mêmes.',
'Oc_Identity_Title' => 'Les produits sont rapprochés par modèle et SKU',
'Oc_Identity_Desc' => 'Le code produit ici est rapproché du modèle et du SKU d\'OpenCart. Gardez-les identiques des deux côtés. Le stock d\'ici fait référence : la boutique est mise à jour à partir de lui après chaque commande.',
'Oc_Options_Title' => 'Options sans variantes',
'Oc_Options_Desc' => 'Les variantes OpenCart ont leur propre stock et correspondent aux variantes d\'ici. Un produit qui n\'a que des options, sans variantes créées, est importé comme un seul produit et son stock n\'est pas réparti par option.',
'Oc_Cancel_Title' => 'Commandes annulées',
'Oc_Cancel_Desc' => 'L\'annulation d\'une commande dans OpenCart annule la vente correspondante ici. Si la vente a déjà été livrée ou comporte un retour, rien n\'est annulé : la vente est signalée dans ses notes et dans les journaux pour que vous l\'examiniez.',
'Oc_Download_Connector_3' => 'Télécharger pour OpenCart 3',
'Oc_Opencart3_Title' => 'Boutiques OpenCart 3',
'Oc_Opencart3_Desc' => 'OpenCart 3 n\'a pas de variantes propres, seulement des options. Un produit avec une seule option (la taille, par exemple) est synchronisé avec un stock par valeur d\'option, qui correspond aux variantes d\'ici. Pour un produit avec plusieurs options, les options sont créées sans stock par combinaison : son stock est tenu sur le produit dans son ensemble, et ses lignes de vente sont imputées au produit.',
'Oc_G_Title' => 'Guide OpenCart',
'Oc_G_Open_Settings' => 'Ouvrir les paramètres OpenCart',
'Oc_G_Your_Setup' => 'Votre configuration',
'Oc_G_Your_Setup_Help' => 'L\'état de cet espace de travail. Les étapes se mettent à jour au fur et à mesure.',
'Oc_G_Step_Install' => 'Installer le {company} Connector sur votre boutique',
'Oc_G_Step_Install_Help' => 'Une petite extension qui donne à {company} l\'accès aux produits, au stock et aux commandes. OpenCart ne propose pas d\'API pour cela par lui-même.',
'Oc_G_Step_Connect' => 'Connecter la boutique',
'Oc_G_Step_Connect_Help' => 'Collez l\'URL de la boutique et la clé secrète affichées sur la page du module dans l\'onglet Connexion, enregistrez, puis lancez Tester la connexion.',
'Oc_G_Step_Connect_Done' => 'Connecté : connecteur {connector} sur OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Activer la synchronisation',
'Oc_G_Step_Enable_Help' => 'Rien ne bouge tant que l\'intégration est désactivée ; les webhooks de la boutique sont acquittés puis ignorés.',
'Oc_G_Step_Products' => 'Lier les produits',
'Oc_G_Step_Products_Help' => 'Récupérez le catalogue de la boutique ou envoyez le vôtre, afin que chaque produit soit lié des deux côtés avant que le stock ne commence à circuler.',
'Oc_G_Step_Products_Done' => '{n} produits et {v} variantes liés.',
'Oc_G_Step_Orders' => 'Recevoir les commandes',
'Oc_G_Step_Orders_Help' => 'Une fois la connexion établie, les nouvelles commandes arrivent d\'elles-mêmes. Passez une commande de test dans la boutique pour la voir apparaître dans Ventes.',
'Oc_G_Step_Orders_No_Webhook' => 'Des commandes ont été importées, mais aucune n\'est encore arrivée par une notification de la boutique. Si la boutique ne peut pas joindre cette adresse, les commandes arrivent quand même grâce à la vérification effectuée toutes les quelques minutes.',
'Oc_G_Step_Orders_Done' => 'La boutique envoie les notifications de commande.',
'Oc_G_Install_Title' => 'Installer le connecteur',
'Oc_G_Install_Intro' => 'Choisissez votre version d\'OpenCart. Le connecteur s\'installe via l\'installateur d\'extensions d\'OpenCart ; aucun fichier n\'est modifié à la main.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Téléchargez le connecteur pour OpenCart 4.',
'Oc_G_I4_2' => 'Dans l\'administration OpenCart, ouvrez {path}, envoyez le fichier et cliquez sur Install à côté.',
'Oc_G_I4_3' => 'Ouvrez {path}, trouvez {name} et cliquez sur Install, puis sur Edit.',
'Oc_G_I3_1' => 'Téléchargez le connecteur pour OpenCart 3.',
'Oc_G_I3_2' => 'Dans l\'administration OpenCart, ouvrez {path}, envoyez le fichier et attendez la fin des étapes.',
'Oc_G_I3_3' => 'Ouvrez {path}, trouvez {name} et cliquez sur Install, puis sur Edit.',
'Oc_G_I_4' => 'La page du module affiche l\'URL de la boutique et une clé secrète. Copiez les deux.',
'Oc_G_I_5' => 'De retour ici, collez-les dans l\'onglet Connexion, enregistrez, puis lancez {test}. Cela indique aussi à la boutique où envoyer les notifications de commande.',
'Oc_G_Requirements' => 'Ce dont la boutique a besoin',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 ou 4.0 et versions ultérieures, PHP avec cURL (standard chez tout hébergeur) et une adresse de boutique accessible depuis Internet. Si la boutique se trouve sur un réseau privé, les commandes arrivent quand même grâce à la vérification exécutée toutes les quelques minutes, tant que cet espace de travail peut joindre la boutique.',
'Oc_G_First_Title' => 'La première synchronisation',
'Oc_G_First_Shop_Has' => 'La boutique possède déjà le catalogue',
'Oc_G_First_Shop_Has_Text' => 'Récupérez les produits dans l\'onglet Produits. Les produits sont rapprochés de vos codes produit par modèle ou SKU, et créés s\'ils sont absents ; cochez l\'option de stock pour reprendre les quantités de la boutique comme stock initial.',
'Oc_G_First_Company_Has' => '{company} possède le catalogue',
'Oc_G_First_Company_Has_Text' => 'Envoyez les produits. Les produits manquants sont créés dans la boutique avec leur stock ; les produits existants sont liés par modèle ou SKU, puis mis à jour.',
'Oc_G_First_Both' => 'Les deux côtés ont des produits',
'Oc_G_First_Both_Text' => 'Récupérez d\'abord, pour que les produits existants de la boutique soient liés au lieu d\'être dupliqués, puis envoyez pour créer ce qui manque à la boutique. Gardez des codes produit et des modèles identiques des deux côtés.',
'Oc_G_Stock_Master' => '{company} fait référence pour le stock',
'Oc_G_Stock_Master_Desc' => 'Après la première synchronisation, la quantité en boutique est toujours écrite depuis {company}. Modifier une quantité dans OpenCart n\'a pas d\'effet durable : le prochain mouvement ou la vérification horaire l\'écrase.',
'Oc_G_How_Title' => 'Fonctionnement',
'Oc_G_T_Products' => 'Produits',
'Oc_G_Products_1' => 'Un produit est rapproché par son code ici avec le modèle et le SKU de la boutique. La liaison est mémorisée : renommer un produit par la suite ne la rompt pas.',
'Oc_G_Products_2' => 'Lorsque {company} envoie un produit, il définit le modèle, le SKU, le nom, le prix, le statut et le stock. La description, l\'image et la catégorie ne sont écrites que lorsque le produit est nouveau dans la boutique ou n\'en a pas, afin de conserver les textes rédigés dans OpenCart.',
'Oc_G_Products_3' => 'Un produit masqué de la boutique en ligne ou non vendable ici n\'est pas créé dans la boutique ; s\'il est déjà lié, il y est plutôt désactivé.',
'Oc_G_T_Variants' => 'Variantes et options',
'Oc_G_Variants_4' => 'OpenCart 4 dispose de vraies variantes (un produit avec des choix de couleur et de taille), chacune avec son propre stock. Elles correspondent à vos variantes dans les deux sens, et chacune est rapprochée par son propre modèle.',
'Oc_G_Variants_3' => 'OpenCart 3 n\'a pas de variantes, seulement des options, avec un stock par valeur d\'option. Un produit avec une seule option (la taille, par exemple) est synchronisé avec un stock par valeur, qui correspond à vos variantes. Pour un produit avec plusieurs options, les options sont créées sans stock par combinaison : son stock reste sur le produit dans son ensemble, et ses lignes de vente sont imputées au produit.',
'Oc_G_Variants_Multi' => 'Un produit de la boutique qui n\'a que des options, sans variantes créées, est importé comme un seul produit ; cela est signalé dans les journaux.',
'Oc_G_T_Stock' => 'Stock',
'Oc_G_Stock_1' => 'Lorsque l\'option de stock est activée, chaque mouvement ici (vente, retour, achat, ajustement, transfert) met à jour la boutique en quelques secondes, après la réponse de la page : le caissier n\'attend donc jamais la boutique.',
'Oc_G_Stock_2' => 'Une fois par heure, chaque produit lié est vérifié et corrigé, ce qui couvre les modifications en masse que l\'envoi en temps réel ne voit pas. L\'onglet Stock envoie l\'ensemble à la demande.',
'Oc_G_Stock_3' => 'Les services, les produits marqués comme toujours en stock et les combos dont les composants sont illimités sont affichés comme toujours disponibles dans la boutique. Choisissez un entrepôt dans l\'onglet Connexion pour ne compter que cet entrepôt ; sinon, tous les entrepôts sont additionnés.',
'Oc_G_T_Orders' => 'Commandes et statuts',
'Oc_G_Orders_1' => 'Une commande nouvelle ou modifiée est annoncée immédiatement par la boutique, puis relue via la connexion signée : rien dans la notification elle-même n\'est considéré comme fiable. Toutes les quelques minutes, une vérification récupère ce qu\'une notification aurait manqué. Chaque commande devient une vente avec la référence OC-<order number> ; le client est retrouvé par e-mail ou créé.',
'Oc_G_Col_List' => 'Liste de statuts',
'Oc_G_Col_Meaning' => 'Effet ici',
'Oc_G_Col_Default' => 'Défini depuis votre boutique',
'Oc_G_Default_Commit' => 'Les statuts qui déduisent le stock dans OpenCart (Pending, Processing, Shipped, Complete par défaut)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Les listes sont remplies à partir de votre boutique lors de la première connexion et peuvent être modifiées dans l\'onglet Connexion. Gardez la première liste identique aux statuts qui déduisent le stock dans OpenCart, afin que les deux côtés mouvementent le stock à la même étape.',
'Oc_G_Orders_3' => 'Une commande contenant un article qui ne correspond à aucun produit est mise en attente, et le produit est importé depuis la boutique s\'il y existe. Les commandes en attente sont retentées à chaque vérification planifiée ; après douze tentatives, elles sont journalisées et laissées en attente pour que vous les récupériez à la main.',
'Oc_G_T_Cancel' => 'Annulations et remboursements',
'Oc_G_Cancel_1' => 'Lorsqu\'une commande passe à un statut annulé dans la boutique, sa vente ici est annulée : le stock est restitué, ses paiements sont supprimés et la vente est supprimée, exactement comme si vous la supprimiez depuis la page Ventes.',
'Oc_G_Cancel_2' => 'Une vente déjà livrée, comportant un retour ou acceptée par une administration fiscale n\'est jamais annulée par la boutique. Elle est signalée dans ses notes et dans les journaux pour que vous l\'examiniez.',
'Oc_G_Cancel_3' => 'Si la commande est rétablie par la suite dans la boutique, elle revient sous forme d\'une nouvelle vente.',
'Oc_G_T_Automation' => 'Options d\'automatisation',
'Oc_G_Auto_1' => 'Importer les commandes automatiquement : notifications de commande et vérification planifiée. Désactivée, les commandes n\'arrivent que lorsque vous les récupérez dans l\'onglet Commandes.',
'Oc_G_Auto_2' => 'Envoyer le stock automatiquement : mises à jour du stock en temps réel et vérification horaire. Désactivée, la boutique ne change que lorsque vous envoyez le stock à la main.',
'Oc_G_Auto_3' => 'Envoyer les modifications de produits automatiquement : un produit créé ou modifié ici met à jour la boutique immédiatement. Désactivée, utilisez l\'onglet Produits.',
'Oc_G_T_Faq' => 'Questions',
'Oc_G_Q_Secret' => 'Tester la connexion indique que la clé secrète ne correspond pas',
'Oc_G_A_Secret' => 'Ouvrez le module {company} Connector dans OpenCart et copiez à nouveau la clé secrète ; un module réinstallé en reçoit une nouvelle. Collez-la dans l\'onglet Connexion et enregistrez avant de tester.',
'Oc_G_Q_Clock' => 'Tester la connexion indique que l\'horloge de la boutique est trop décalée',
'Oc_G_A_Clock' => 'Les requêtes signées contiennent l\'heure et sont refusées lorsque les deux horloges diffèrent de plus de cinq minutes. Réglez la date et l\'heure sur le serveur de la boutique.',
'Oc_G_Q_Redirect' => 'Tester la connexion indique que la boutique redirige vers une autre adresse',
'Oc_G_A_Redirect' => 'Votre boutique répond à une autre adresse, généralement en https au lieu de http, ou avec www. Utilisez l\'adresse indiquée dans le message comme URL de la boutique.',
'Oc_G_Q_Not_Answering' => 'Tester la connexion indique que le connecteur n\'a pas répondu',
'Oc_G_A_Not_Answering' => 'L\'adresse n\'est pas une boutique OpenCart, ou le module n\'est pas installé ou est désactivé. Vérifiez l\'URL de la boutique, puis que le {company} Connector apparaît comme installé et activé dans Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Les commandes sont passées dans la boutique mais mettent plusieurs minutes à apparaître',
'Oc_G_A_No_Orders' => 'La boutique ne peut pas joindre cet espace de travail : les commandes n\'arrivent donc que via la vérification planifiée. Regardez l\'adresse {company} sur la page du module : elle doit être accessible depuis le serveur de la boutique. Lancer Tester la connexion l\'enregistre à nouveau.',
'Oc_G_Q_Stock_Wrong' => 'Une quantité dans la boutique est erronée',
'Oc_G_A_Stock_Wrong' => 'Envoyez le stock depuis l\'onglet Stock : cela réécrit chaque produit lié à partir des quantités d\'ici. Si l\'écart persiste, vérifiez que l\'option de stock est activée et que personne ne modifie les quantités dans OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Un produit apparaît en rupture de stock dans la boutique alors qu\'il y a du stock ici',
'Oc_G_A_Out_Of_Stock' => 'Sur OpenCart 3, un produit avec plusieurs options tient son stock sur le produit dans son ensemble ; vérifiez la quantité du produit dans la boutique plutôt que celle de ses options. Pour tout produit, envoyez le stock une fois et consultez les journaux de ce produit.',
'Oc_G_Q_Held' => 'Les journaux indiquent qu\'une commande a été mise en attente',
'Oc_G_A_Held' => 'L\'un de ses articles ne correspond à aucun produit ici et n\'a pas pu être importé depuis la boutique, généralement parce que le produit y a été supprimé. Créez ou liez le produit, puis récupérez les commandes dans l\'onglet Commandes.',
'Oc_G_Q_Deleted_Sale' => 'J\'ai supprimé une vente importée et elle est revenue',
'Oc_G_A_Deleted_Sale' => 'Tant que la commande est active dans la boutique, la prochaine notification ou vérification l\'importe à nouveau. Annulez plutôt la commande dans la boutique, ce qui annule la vente ici.',
'Oc_G_Q_Uninstall' => 'Comment déconnecter la boutique ?',
'Oc_G_A_Uninstall' => 'Désactivez la synchronisation dans l\'onglet Connexion ; rien ne bouge tant qu\'elle est désactivée. Pour retirer l\'intégration de la boutique, désinstallez le {company} Connector dans Extensions → Modules.',
'Oc_Full_Guide' => 'Ouvrir le guide complet',
'Comm_Receipt_Account_Hint' => 'Le compte de caisse ou bancaire d\'où sort ce versement. Son solde diminue du montant et la comptabilité passe l\'écriture Charge de commissions sur ventes (Sales Commission Expense) en contrepartie.',
'Comm_G_Q_Ledger' => 'Quel est l\'effet d\'un versement de commission en comptabilité ?',
'Comm_G_A_Ledger' => 'Lorsque vous créez un reçu et choisissez un compte, le solde de ce compte diminue du montant du reçu et, si les écritures automatiques sont activées, une écriture est passée : débit Charge de commissions sur ventes (Sales Commission Expense, 5200-COMM), crédit du compte de caisse ou bancaire choisi. Sans compte sélectionné, le crédit est imputé au compte Caisse (Cash) par défaut et aucun solde ne change.',
'Hide_Zero_Decimals' => 'Masquer les décimales nulles',
'Sys_Hide_Zero_Decimals_Help' => 'Afficher les montants entiers sans leurs décimales : 100.00 devient 100, tandis que 100.50 conserve ses décimales. Affichage uniquement ; les valeurs enregistrées et les calculs ne changent pas.',
'Sys_Currency_Position_Before_NoSpace' => 'Avant le montant, sans espace',
'Sys_Currency_Position_After_NoSpace' => 'Après le montant, sans espace',
'Supplier_Wallet' => 'Portefeuille fournisseur',
'Supplier_Wallets' => 'Portefeuilles fournisseurs',
'Supplier_Ledger' => 'Grand livre fournisseur',
'Sys_Supplier_Wallet_Help' => 'Gérer des soldes prépayés auprès des fournisseurs : recharges, avoirs de retour et paiement des achats depuis le portefeuille. Nécessite la fonctionnalité Portefeuille fournisseur dans le plan.',
'SW_Allow_Negative' => 'Autoriser un solde de portefeuille négatif',
'Sys_SW_Allow_Negative_Help' => 'Permettre à un paiement d\'achat de mettre le portefeuille fournisseur à découvert au lieu d\'être refusé.',
'SW_Wallet_Balance' => 'Solde du portefeuille',
'SW_Net_After_Wallet' => 'Net après portefeuille',
'SW_Balance_After' => 'Solde après',
'SW_Balances' => 'Soldes',
