'SW_Unfreeze' => 'Dégeler le portefeuille',
'SW_Freeze_Confirm' => 'Un portefeuille gelé refuse tout mouvement jusqu\'à ce qu\'il soit dégelé. Continuer ?',
'SW_Unfreeze_Confirm' => 'Autoriser à nouveau les mouvements de portefeuille pour ce fournisseur ?',
'SW_Only_With_Balance' => 'Uniquement les portefeuilles avec un solde',
'SW_Top_Up' => 'Recharger',
'SW_Refund' => 'Rembourser depuis le portefeuille',
'SW_Adjust' => 'Ajuster le solde',
'SW_Top_Up_Help' => 'Argent versé d\'avance au fournisseur. Il sort du compte choisi et reste dans le portefeuille jusqu\'à ce qu\'il soit dépensé en achats.',
'SW_Refund_Help' => 'Le fournisseur rembourse une partie de l\'avance en espèces. Le montant sort du portefeuille et arrive sur le compte choisi.',
'SW_Adjust_Help' => 'Correction manuelle sans mouvement de trésorerie. Un motif est obligatoire et il est conservé dans le grand livre.',
'SW_Adjust_Credit' => 'Ajouter au portefeuille',
'SW_Adjust_Debit' => 'Déduire du portefeuille',
'SW_Pay_From_Wallet' => 'Payer depuis le portefeuille fournisseur',
'SW_Pay_From_Wallet_Help' => 'Le montant est prélevé sur le solde prépayé détenu chez ce fournisseur. Aucun compte ni mode de paiement n\'est nécessaire.',
'SW_Credit_To_Wallet' => 'Créditer le portefeuille fournisseur',
'SW_Credit_To_Wallet_Help' => 'Au lieu d\'un remboursement en espèces, le fournisseur règle ce retour sous forme de crédit sur le portefeuille, utilisable pour de prochains achats.',
'SW_Disabled_Hint' => 'Le portefeuille fournisseur est désactivé. Activez-le dans Paramètres du système > Fonctionnalités (il nécessite aussi la fonctionnalité Portefeuille fournisseur dans le plan).',
'SW_Src_top_up' => 'Recharge',
'SW_Src_refund' => 'Remboursement',
'SW_Src_adjustment' => 'Ajustement',
'SW_Src_purchase_payment' => 'Paiement d\'achat',
'SW_Src_return_credit' => 'Avoir de retour',
'SW_Src_opening_balance_payment' => 'Paiement du solde d\'ouverture',
'SW_Src_reversal' => 'Contre-passation',
'SW_Err_wallet_disabled' => 'Le portefeuille fournisseur n\'est pas activé.',
'SW_Err_wallet_frozen' => 'Ce portefeuille fournisseur est gelé.',
'SW_Err_wallet_insufficient_balance' => 'Solde du portefeuille insuffisant.',
'SW_Err_wallet_invalid_amount' => 'Le montant doit être supérieur à zéro.',
'SW_Perm_View' => 'Portefeuille fournisseur : consulter',
'SW_Perm_Manage' => 'Portefeuille fournisseur : gérer',
'SW_Top_Ups_Total' => 'Recharges (total)',
'SW_Spent_Total' => 'Dépensé depuis le portefeuille',
'Purchases_Grand' => 'Achats (total général)',
'Purchases_Paid' => 'Achats (payé)',
'Purchases_Due' => 'Achats (dû)',
'Purchase_Update_Selling_Price' => 'Modifier le prix de vente lors de l\'achat',
'Sys_Purchase_Update_Selling_Price_Help' => 'Ajoute un champ prix de vente à chaque ligne d\'achat, à côté du coût. Un prix saisi à cet endroit remplace le prix de vente du produit lors de l\'enregistrement de l\'achat ; laissez-le vide pour conserver le prix actuel.',
'Current_Selling_Price' => 'Prix de vente actuel',
'Keep_Current_Price' => 'Laisser vide pour conserver le prix actuel',
'Selling_Price_In_Base_Currency' => 'Saisi dans la devise de base',
'Purchase_Update_Product_Cost' => 'Mettre à jour le coût du produit lors de l\'achat',
'Sys_Purchase_Update_Product_Cost_Help' => 'Lorsqu\'un achat reçu est enregistré, le coût de chaque produit devient le coût unitaire net de sa ligne d\'achat (après remise de ligne, hors taxe, par unité de base). Les achats en attente et commandés ne le modifient pas.',
'Show_Stock_In_Search_Results' => 'Afficher le stock dans les résultats de recherche',
'Show_Stock_In_Search_Results_Help' => 'Afficher la quantité disponible de chaque produit à côté de celui-ci dans la liste de recherche du POS.',
'Layout_6_Tabular' => 'Mise en page 6 - Tableau',
'Show_Signature_Line' => 'Afficher la ligne de signature',
'Show_Signature_Line_Desc' => 'Imprime une ligne de signature client vierge sous le reçu, quelle que soit la mise en page sélectionnée.',
'Customer_Signature' => 'Signature du client',
'Set_Signature_Label' => 'Libellé de la ligne de signature (vide = « Signature du client »)',
'Oc_Code_Source' => 'Source du code produit',
'Oc_Code_Source_Help' => 'Le champ OpenCart qui sert de code produit ici. Le modèle est obligatoire dans OpenCart : certaines boutiques y saisissent donc une catégorie ou un type de produit et conservent le véritable code article dans SKU, ISBN, UPC, EAN, JAN ou MPN ; choisissez ce champ pour une telle boutique. Le modèle, puis le SKU, sont utilisés lorsque le champ choisi est vide. S\'applique aux produits récupérés, au rapprochement et aux envois.',
'Oc_Code_Source_Model' => 'Modèle (par défaut)',
