'Oc_L_H_Secret' => 'La clé secrète enregistrée ici n\'est pas celle du module connecteur dans OpenCart : la boutique rejette donc chaque appel.',
'Oc_L_F_Secret' => 'Dans OpenCart, ouvrez Extensions → Modules → le connecteur, copiez la clé secrète affichée, collez-la dans l\'onglet Connexion et enregistrez. La réinstallation du module crée une nouvelle clé secrète.',
'Oc_L_H_Clock' => 'L\'horloge du serveur OpenCart diffère trop de la nôtre : les requêtes signées semblent donc expirées.',
'Oc_L_F_Clock' => 'Demandez à l\'hébergeur de régler l\'heure du serveur (NTP). Un écart de quelques minutes suffit à bloquer la connexion.',
