'Oc_L_F_Unreachable' => 'Ouvrez l\'URL de la boutique dans un navigateur pour vérifier qu\'elle est en ligne, confirmez que le module connecteur est installé et activé, et vérifiez qu\'aucun pare-feu ni mode maintenance ne bloque notre serveur.',
'Oc_L_H_Redirect' => 'La boutique renvoie les visiteurs vers une autre adresse (par exemple de http vers https, ou vers www).',
'Oc_L_F_Redirect' => 'Enregistrez l\'adresse indiquée dans le message comme URL de la boutique dans l\'onglet Connexion.',
'Oc_L_H_Not_Configured' => 'L\'URL de la boutique ou la clé secrète est manquante : rien ne peut encore être envoyé.',
'Oc_L_F_Not_Configured' => 'Renseignez l\'URL de la boutique et la clé secrète dans l\'onglet Connexion, enregistrez et lancez Tester la connexion.',
'Oc_L_H_Model_Taken' => 'Un produit envoyé à la boutique a un code qu\'un autre produit de la boutique, ou l\'une de ses variantes, utilise déjà comme modèle.',
'Oc_L_F_Model_Taken' => 'Modifiez le code de l\'un des deux produits, ou récupérez d\'abord les produits afin que le produit existant de la boutique soit lié au lieu d\'être recréé.',
'Oc_L_H_Model_Missing' => 'Un produit envoyé à la boutique n\'a pas de code ou pas de nom. OpenCart exige les deux.',
'Oc_L_F_Model_Missing' => 'Donnez un code et un nom au produit ici, puis envoyez-le à nouveau.',
'Oc_L_H_Held' => 'Une commande a été reçue mais certains de ses articles ne correspondent à aucun produit ici : elle est donc en attente et aucune vente n\'a été créée.',
'Oc_L_F_Held' => 'Créez ou récupérez les produits manquants (les articles sont listés ci-dessous), puis récupérez à nouveau les commandes. Les commandes en attente sont retentées automatiquement quelques fois.',
'Oc_L_H_Given_Up' => 'Une commande n\'a pas pu être importée après plusieurs tentatives et n\'est plus retentée.',
'Oc_L_F_Given_Up' => 'Assurez-vous que ses produits existent ici, puis récupérez les commandes à la main depuis l\'onglet Commandes avec une date antérieure à la commande.',
'Oc_L_H_Review' => 'Une commande a été annulée dans OpenCart après que la vente ici a été livrée ou retournée : le stock n\'a donc pas été restitué automatiquement.',
'Oc_L_F_Review' => 'Ouvrez la vente et décidez s\'il faut retourner les articles ou la laisser telle quelle.',
'Oc_L_H_Reversed' => 'Une commande a été annulée dans OpenCart et la vente correspondante ici a été annulée, ce qui a remis son stock en place.',
'Oc_L_H_Backlog' => 'La récupération planifiée des commandes a trouvé plus de commandes qu\'elle n\'en traite en une exécution et reprendra la prochaine fois.',
'Oc_L_F_Backlog' => 'Récupérez les commandes à la main depuis l\'onglet Commandes pour résorber le retard.',
'Oc_L_H_Paused' => 'Les envois automatiques ont été suspendus un moment car la boutique ne répondait plus. Les modifications effectuées entre-temps sont envoyées dès qu\'elle répond à nouveau.',
'Oc_L_F_Paused' => 'Vérifiez que la boutique est en ligne. Rien d\'autre n\'est nécessaire ; la file d\'attente reprend d\'elle-même.',
'Oc_L_H_Busy' => 'Deux envois automatiques se sont chevauchés et l\'un s\'est effacé. Rien n\'a été perdu.',
'Oc_L_H_Codes_Suffixed' => 'Certains produits récupérés portent un code qu\'un autre produit de la boutique avait déjà ici, généralement parce que le champ de code choisi est vide ou contient un nom de catégorie. Ils ont été créés avec l\'id OpenCart ajouté, afin que deux produits ne fusionnent pas.',
'Oc_L_F_Codes_Suffixed' => 'Renseignez le champ de code (Model, SKU, ISBN…) dans OpenCart pour les produits listés ci-dessous, ou choisissez une autre Source du code produit dans l\'onglet Connexion, puis réinitialisez les liaisons de produits et récupérez à nouveau.',
'Oc_L_H_Options' => 'Certains produits de la boutique ont des options (taille, couleur…) sans stock par variante : le stock est donc suivi pour le produit dans son ensemble.',
'Oc_L_F_Options' => 'Aucune action requise. Pour suivre le stock par option, transformez ces options en variantes dans OpenCart 4, ou utilisez une seule option par produit dans OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'Cette page de produits a été lue depuis la boutique. Créé signifie un nouveau produit ici ; mis à jour signifie qu\'il existait déjà et a été lié.',
'Oc_L_H_Pull_Failed' => 'Certains produits de cette page n\'ont pas pu être enregistrés ici ; chacun est listé ci-dessous avec le motif.',
'Oc_L_F_Pull_Failed' => 'Corrigez les produits listés dans OpenCart (un nom ou un code manquant en est la cause habituelle) et récupérez à nouveau. Seuls les produits en échec sont concernés.',
'Oc_L_H_Push_Warnings' => 'Les produits ont été envoyés à la boutique, mais celle-ci a signalé des problèmes pour certains d\'entre eux, comme une image qu\'elle n\'a pas pu télécharger.',
'Oc_L_F_Push_Warnings' => 'Lisez la liste ci-dessous. Les images doivent être accessibles depuis le serveur de la boutique ; tout le reste a été enregistré tel qu\'envoyé.',
'Oc_L_H_Missing_Remote' => 'Le stock a été envoyé, mais certains produits liés n\'existent plus dans la boutique.',
'Oc_L_F_Missing_Remote' => 'Envoyez les produits pour les recréer dans la boutique, ou réinitialisez les liaisons de produits s\'ils ont été supprimés volontairement.',
'Oc_L_H_Generic' => 'Une étape de synchronisation a échoué. Le message ci-dessus est le motif donné par la boutique ou par le serveur.',
'Oc_L_F_Generic' => 'Lancez Tester la connexion dans l\'onglet Connexion. Si le test réussit, réessayez l\'étape ; s\'il échoue, suivez l\'indication qu\'il donne.',
'Oc_L_H_Code_Fallback' => 'Certains produits de cette page sont arrivés sans valeur dans le champ choisi comme Source du code produit : leur modèle (souvent un nom de catégorie) a donc été utilisé comme code.',
'Oc_L_F_Code_Fallback' => 'Consultez « Produits portant chaque champ » ci-dessous. Si le champ choisi affiche 0 alors que la boutique possède bien ces valeurs, la boutique les conserve sous un autre nom d\'identifiant ; ouvrez l\'un des produits listés dans OpenCart (onglet Data, Product Codes) et envoyez-nous ce qu\'il affiche. Sinon, renseignez le champ dans OpenCart pour les produits listés et récupérez à nouveau.',
'Oc_L_H_Old_Connector' => 'La boutique utilise encore un connecteur antérieur à la version 1.1.0, qui n\'envoie que le modèle et le SKU : le champ de code choisi n\'arrive donc jamais et le modèle a été utilisé.',
'Oc_L_F_Old_Connector' => 'Téléchargez à nouveau le connecteur, désinstallez et supprimez l\'ancien dans OpenCart (Extensions → Installer), installez le nouveau, collez sa nouvelle clé secrète dans l\'onglet Connexion et lancez Tester la connexion. La page doit afficher Connecteur 1.1.0 avant que vous ne récupériez les produits.',
